INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-1-section-2','cet4-2025-06-1',1,'cloze','选词填空（26–35）','In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single line through the centre. You may not use any of the words in the bank more than once.','["Psychologists have long been interested in how we construct our identities and the sorts of strategies that we use to present ourselves in society. New findings suggest that the kinds of [26] ______ and strategic self-presentation behaviour we see in adults appear at a much younger age than [27] ______ known.","Research shows that a child’s awareness of social standing comes from adults. Like grown-ups, kids want to be [28] ______ by those they admire. Interactive experiences may provide opportunities for children to learn about what [29] ______ a desirable reputation and the kinds of strategies that are effective for [30] ______ a good reputation in their social environment.","Five-year-olds aren’t just aware of their reputations, they also behave strategically to alter their outward image. They will [31] ______ their behaviour in order to appear moral or socially good in the eyes of key observers. While we know that adults use a large variety of attributes to manage and create impressions, we don’t yet know whether children [32] ______ and use the fact that different attributes are valuable at different times to different [33] ______ . It’s important for us to further consider where in this process children succeed in controlling their reputation and where they [34] ______ .","A question to think about is, “What happens even earlier than age five?” Children don’t just show up to the first day of kindergarten and have the idea of reputation pop [35] ______ into existence. The logical question to ask is, “What happens even earlier?”"]','["Psychologists have long been interested in how we construct our identities and the sorts of strategies that we use to present ourselves in society. New findings suggest that the kinds of complex and strategic self-presentation behaviour we see in adults appear at a much younger age than previously known.","Research shows that a child’s awareness of social standing comes from adults. Like grown-ups, kids want to be accepted by those they admire. Interactive experiences may provide opportunities for children to learn about what constitutes a desirable reputation and the kinds of strategies that are effective for building a good reputation in their social environment.","Five-year-olds aren’t just aware of their reputations, they also behave strategically to alter their outward image. They will vary their behaviour in order to appear moral or socially good in the eyes of key observers. While we know that adults use a large variety of attributes to manage and create impressions, we don’t yet know whether children understand and use the fact that different attributes are valuable at different times to different audiences. It’s important for us to further consider where in this process children succeed in controlling their reputation and where they struggle.","A question to think about is, “What happens even earlier than age five?” Children don’t just show up to the first day of kindergarten and have the idea of reputation pop suddenly into existence. The logical question to ask is, “What happens even earlier?”"]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
