INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-1-2','cet4-2025-06-1',200,1,'These figures showed that the number of pupils that sat exams in Design and Technology fell 10 percent from 204,788 to 185,279 last year.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-2-1','cet4-2025-06-1',201,0,'Chief executive John Kampfner of the Creative Industries Federation thinks that this drop in figures has worrying implications for the skills pipeline in Britain’s hugely successful arts and creative industries.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-2-2','cet4-2025-06-1',201,1,'He said, “We already have skills shortages in many jobs such as animation (动画制作) and special effects.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-2-3','cet4-2025-06-1',201,2,'He added: “Engineering, which requires a similar mix of creative and technical skills, also has recruitment problems.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-3-1','cet4-2025-06-1',202,0,'Many other designers and architects have expressed concern over the future supply of home-grown talent for UK firms, and industry bodies have pointed out that there has been a lack of roots-level support.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-3-2','cet4-2025-06-1',202,1,'However, if these designers had visited the Design Museum shop in London earlier this year their fears may have been eased.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-3-3','cet4-2025-06-1',202,2,'With £10 to spend, they could have bought a fascinating children’s toy called “Dazzle Racer”.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-3-4','cet4-2025-06-1',202,3,'An automotive cylinder (圆柱体), it included a wind-up, elastic (有弹性的)-band-powered mechanism, minimal parts, all 100 percent recycled, and lots of stickers.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-3-5','cet4-2025-06-1',202,4,'It was good fun, simple, eye-catching and very original.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-4-1','cet4-2025-06-1',203,0,'Well, you’d expect the Design Museum to commission and make some interesting items, but this one was different.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-4-2','cet4-2025-06-1',203,1,'Designed by a group of six Year 9 and Year 10 boys from Finchley Catholic High School, the toy was the winning entry in the museum’s 2015 Design Ventura competition, which brings the business of design to life for students aged 13 to 16 by challenging them to develop a new creative, sustainable and commercially feasible product for the Design Museum shop and attracts hundreds of entries nationwide.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-5-1','cet4-2025-06-1',204,0,'“We did Design Ventura in my previous school,” says Liam Hourican, Finchley Catholic High School’s design technology curriculum leader, “Then when I changed schools four years ago, I introduced it here because it helps to develop so many skills.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-6-1','cet4-2025-06-1',205,0,'The theme for last year’s competition was “Move”, and Hourican began with three groups working in lunch breaks and after school before selecting the group with the most innovative idea.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-6-2','cet4-2025-06-1',205,1,'Each participating school may submit just one proposal.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-6-3','cet4-2025-06-1',205,2,'“It’s the taking part and doing the work which is important,” he says.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-6-4','cet4-2025-06-1',205,3,'“And I never dreamt we’d win.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-7-1','cet4-2025-06-1',206,0,'Catherine Ritman Smith, head of learning at the Design Museum, is expecting around 10,000 participants aged 13 to 16 to take part this year and says that the project—funded by Deutsche Bank as part of its youth engagement programme Born To Be—is the biggest event in the museum’s calendar.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-7-2','cet4-2025-06-1',206,1,'“We started Design Ventura with around 800 young people in 2010 and it has grown steadily since,” she says.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-7-3','cet4-2025-06-1',206,2,'“Teachers like it because the skills are all transferable and it helps to validate the value of design as a subject,” she explains, telling me that nearly 600 schools have taken part so far.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-1','cet4-2025-06-1',207,0,'So how does the competition work?','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-2','cet4-2025-06-1',207,1,'A single-word theme is announced in the summer.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-3','cet4-2025-06-1',207,2,'This year it is “Change”.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-4','cet4-2025-06-1',207,3,'Schools work with groups to produce imaginative design ideas for a product in simple materials that could sell for £10 in the Design Museum shop.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-5','cet4-2025-06-1',207,4,'Participating schools then register by November and eventually submit their design idea.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-6','cet4-2025-06-1',207,5,'Along the way there is training and support for teachers and tutoring for students from designers.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-8-7','cet4-2025-06-1',207,6,'An additional bonus is when the winners see their design on sale in the spring of the following year.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-9-1','cet4-2025-06-1',208,0,'Hourican and his pupils have happy memories of spending a whole day at the museum, having been selected as one of 10 shortlisted schools to present their idea to a panel of judges, including designer Jasper Conran.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-9-2','cet4-2025-06-1',208,1,'Then they worked with the Kin Design Studio in Shoreditch, met designers at their school and attended a lunch with Deutsche Bank employees.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-9-3','cet4-2025-06-1',208,2,'The students helped to make decisions and there were plenty of discussions—they changed the product’s name, for example.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-10-1','cet4-2025-06-1',209,0,'“One of the really useful things about this competition,” says Hourican, “is that there’s a commercial element because the product is going on sale for real and the boys had to learn about budgeting and marketing, as well as designing their game.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-10-2','cet4-2025-06-1',209,1,'Profits go to charity.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-10-3','cet4-2025-06-1',209,2,'“The winning team chooses where it wants the profits to go,” says Ritman Smith.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-10-4','cet4-2025-06-1',209,3,'“The Finchley Catholic High School product raised about £1,000 for Great Ormond Street Hospital.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-10-5','cet4-2025-06-1',209,4,'Winning entries in past years have included a make-your-own cloth kit called Dove Bunting and a threefold, wallet-sized travel game with goals at each end, called Badoiiing.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-11-1','cet4-2025-06-1',210,0,'It costs the schools nothing to participate in Design Ventura; the professional designers provide their services for free.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-11-2','cet4-2025-06-1',210,1,'Among them are architect Asif Khan, a Design Museum trustee who has worked as designer-in-residence at the museum, helping emerging architects.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-11-3','cet4-2025-06-1',210,2,'He has recently been commissioned to design the new Museum of London building in Smithfield.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-1','cet4-2025-06-1',211,0,'Another is television presenter and interior designer Naomi Cleaver, who is one of the competition’s judges.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-2','cet4-2025-06-1',211,1,'“I’m very keen to encourage young people,” she says, observing that design brings together other subjects such as literature, art, history, geography and science.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-3','cet4-2025-06-1',211,2,'“Now that design education is limited in the curriculum, I’m all in favour of competitions such as Design Ventura, which helps to bring the standard curriculum to life,” says Cleaver.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-4','cet4-2025-06-1',211,3,'“And the judging day is terrific fun.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-5','cet4-2025-06-1',211,4,'Some of these students are very imaginative.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-6','cet4-2025-06-1',211,5,'One group presented their idea in the form of a puppet show and we see some marvelous demonstration models.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-12-7','cet4-2025-06-1',211,6,'I’m always impressed by the levels of confidence and the support the students get from their teachers.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-13-1','cet4-2025-06-1',212,0,'Ritman Smith adds: “Design technology has become a tricky subject to make a case for, and we’ve heard of departments closing in some schools.','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-3-sentence-13-2','cet4-2025-06-1',212,1,'We find that if pupils take part in Design Ventura in Year Nine it can be the trigger which leads them to opt for it at General Certificate of Secondary Education, so we are helping to keep alive something which is crucial to industry and entrepreneurship.”','cet4-2025-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-1-section-4','cet4-2025-06-1',3,'reading','仔细阅读 · Passage One（46–50）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["New research suggests that pandas may be at risk of dying out because they are too comfortable. Experts say too much happiness can stop the bears from searching for new mates.","Environmentalists have long believed that building roads or homes near the bears may threaten their survival by “reducing or fragmenting their natural: habitats”, The Times reported. But the new research suggests that a “modest degree of discomfort and fragmentation” may actually help preserve panda populations.","The research was conducted by scientists from Michigan State University. It concluded that pandas fail to wander off in search of new mates if they find their habitat too comfortable, resulting in a lack of vital genetic diversity.","For their study—outlined in a paper in the journal Conservation Biology—the team looked at genetic diversity and spread among a Chinese panda population. The ideal level of perfectly livable habitat was found to be only 80% of an area, with the remainder either too harsh or too affected by human activity.","The experts concluded that pandas should ideally “be happy enough to thrive, but not so content that they don’t want to move around and find new mates”.","Their conclusions about what The Guardian described as this “sweet spot” are in line with the so-called Goldilocks principle: that there can be just the right amount of something. The concept has been applied to a wide range of disciplines, from developmental psychology to economics and engineering.","Claudio Sillero, a professor of conservation biology at Oxford University, told the newspaper that the new findings could have implications beyond panda conservation.","“Most large animals that eat meat live in increasingly fragmented landscapes,” said Sillero, who was not involved in the research. “It may well be that the messy nature of their relationship with human efforts induces more animals to scatter or travel further, and might result in greater genetic connectivity and enhanced population persistence.”","The most recent count of pandas found that there were more than 1,800 left in the wild, putting them on the list of vulnerable, but not endangered, species."]','["New research suggests that pandas may be at risk of dying out because they are too comfortable. Experts say too much happiness can stop the bears from searching for new mates.","Environmentalists have long believed that building roads or homes near the bears may threaten their survival by “reducing or fragmenting their natural: habitats”, The Times reported. But the new research suggests that a “modest degree of discomfort and fragmentation” may actually help preserve panda populations.","The research was conducted by scientists from Michigan State University. It concluded that pandas fail to wander off in search of new mates if they find their habitat too comfortable, resulting in a lack of vital genetic diversity.","For their study—outlined in a paper in the journal Conservation Biology—the team looked at genetic diversity and spread among a Chinese panda population. The ideal level of perfectly livable habitat was found to be only 80% of an area, with the remainder either too harsh or too affected by human activity.","The experts concluded that pandas should ideally “be happy enough to thrive, but not so content that they don’t want to move around and find new mates”.","Their conclusions about what The Guardian described as this “sweet spot” are in line with the so-called Goldilocks principle: that there can be just the right amount of something. The concept has been applied to a wide range of disciplines, from developmental psychology to economics and engineering.","Claudio Sillero, a professor of conservation biology at Oxford University, told the newspaper that the new findings could have implications beyond panda conservation.","“Most large animals that eat meat live in increasingly fragmented landscapes,” said Sillero, who was not involved in the research. “It may well be that the messy nature of their relationship with human efforts induces more animals to scatter or travel further, and might result in greater genetic connectivity and enhanced population persistence.”","The most recent count of pandas found that there were more than 1,800 left in the wild, putting them on the list of vulnerable, but not endangered, species."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-4-q-46','cet4-2025-06-1-section-4',0,'choice','46. What do we learn from new research about pandas?','[{"key":"A","text":"They are losing habitat due to the building of roads and houses."},{"key":"B","text":"They have stopped seeking new mates for reproduction."},{"key":"C","text":"They may not adapt to the fragmentation of their habitat."},{"key":"D","text":"They may cease to exist as a result of enjoying too good a life."}]','D','参考答案 D，依据原文整理。首段指出大熊猫可能因环境过于舒适、缺少寻找新伴侣的动力而面临灭绝风险。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-4-q-47','cet4-2025-06-1-section-4',1,'choice','47. What can we conclude from the new research by scientists at Michigan State University?','[{"key":"A","text":"Environmentalists’ long-time belief regarding panda conservation may be misleading."},{"key":"B","text":"Housing development near pandas’ homes may threaten their survival."},{"key":"C","text":"Pandas’ natural habitats are becoming less suitable for reproduction."},{"key":"D","text":"The increased panda population is attributed to the fragmentation of their habitat."}]','A','参考答案 A，依据原文整理。新研究认为适度的不舒适与栖息地碎片化可能有利于种群，与环保人士长期持有的看法不同。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-4-q-48','cet4-2025-06-1-section-4',2,'choice','48. What is the experts’ conclusion regarding pandas?','[{"key":"A","text":"It is urgent to provide an ideal habitat for them to thrive."},{"key":"B","text":"It is very important to preserve their genetic diversity."},{"key":"C","text":"Their chances of finding new mates have a lot to do with their habitat."},{"key":"D","text":"Their environment for survival has been continuously worsening."}]','C','参考答案 C，依据原文整理。研究及专家结论都强调栖息地的舒适程度影响熊猫迁移并寻找新伴侣的动力。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-4-q-49','cet4-2025-06-1-section-4',3,'choice','49. What can we infer from the passage about the Goldilocks principle?','[{"key":"A","text":"It needs to be confirmed by more studies on pandas."},{"key":"B","text":"It applies to the preservation of pandas too."},{"key":"C","text":"It has implications for future panda research."},{"key":"D","text":"It can be used to locate the right spot for pandas."}]','B','参考答案 B，依据原文整理。文章用 Goldilocks principle 解释适度舒适的理想状态，说明这一原则同样适用于熊猫保护。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-4-q-50','cet4-2025-06-1-section-4',4,'choice','50. What can the new findings do according to Professor Sillero?','[{"key":"A","text":"Help discover new ways for the conservation of pandas."},{"key":"B","text":"Help remove pandas from the list of endangered species."},{"key":"C","text":"Shed light on the conservation of most large meat-eating animals."},{"key":"D","text":"Show the complexity of interactions between humans and animals."}]','C','参考答案 C，依据原文整理。Sillero 指出研究的意义可能超出熊猫保护，并以大型食肉动物的基因连通性和种群延续为例。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
