INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-4-sentence-9-1','cet4-2025-06-1',308,0,'The most recent count of pandas found that there were more than 1,800 left in the wild, putting them on the list of vulnerable, but not endangered, species.','cet4-2025-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-1-section-5','cet4-2025-06-1',4,'reading','仔细阅读 · Passage Two（51–55）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["With those born with natural talents, it feels as if they excel without really trying. But what about those of us who don’t have a natural talent? We’ve been told all our lives that if you work hard, you too can succeed. But with the release of Angela Duckworth’s Grit, we are given a new key to success.","“As much as talent counts, effort counts twice,” says Duckworth in Grit. She introduces a new concept that talent may be overrated, and if you want real success, what you need is grit, the perfect combination of passion and persistence. Even if you have natural talent, it’s nothing without grit.","Duckworth says grit is the difference between success and failure. A person who has grit is more likely to succeed than a person who does not. When we think about attaining success — whether it’s landing that job or learning that new skill—our thoughts are immediately burdened by all the things we must first learn. If you want that new job, you have to learn the job skills, then the interview skills, then the dress part — and you must be perfect at all of them. Grit is different because it tells us that perfection isn’t the goal.","Grit lifts the unreasonable expectations off our shoulders. Grit tells us that the door is open wider than we first thought possible. Grit allows us to redefine our goals. Think about it: what’s something you’ve always wanted to do, but gave up because you “don’t have the skills for it”? What’s something you love but aren’t good at?","The real workings of grit are to have sustainable passion and continue to try. Effort means more than your natural ability. Even if you haven’t mastered a skill, grit tells you that you can still succeed if you can transform your passion into action. In a way, Duckworth is giving new hope to people who have shut the doors on their dreams. She is saying it is possible that you can accomplish anything. If at first you fail, then try one more time with grit."]','["With those born with natural talents, it feels as if they excel without really trying. But what about those of us who don’t have a natural talent? We’ve been told all our lives that if you work hard, you too can succeed. But with the release of Angela Duckworth’s Grit, we are given a new key to success.","“As much as talent counts, effort counts twice,” says Duckworth in Grit. She introduces a new concept that talent may be overrated, and if you want real success, what you need is grit, the perfect combination of passion and persistence. Even if you have natural talent, it’s nothing without grit.","Duckworth says grit is the difference between success and failure. A person who has grit is more likely to succeed than a person who does not. When we think about attaining success — whether it’s landing that job or learning that new skill—our thoughts are immediately burdened by all the things we must first learn. If you want that new job, you have to learn the job skills, then the interview skills, then the dress part — and you must be perfect at all of them. Grit is different because it tells us that perfection isn’t the goal.","Grit lifts the unreasonable expectations off our shoulders. Grit tells us that the door is open wider than we first thought possible. Grit allows us to redefine our goals. Think about it: what’s something you’ve always wanted to do, but gave up because you “don’t have the skills for it”? What’s something you love but aren’t good at?","The real workings of grit are to have sustainable passion and continue to try. Effort means more than your natural ability. Even if you haven’t mastered a skill, grit tells you that you can still succeed if you can transform your passion into action. In a way, Duckworth is giving new hope to people who have shut the doors on their dreams. She is saying it is possible that you can accomplish anything. If at first you fail, then try one more time with grit."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-5-q-51','cet4-2025-06-1-section-5',0,'choice','51. What does the passage say about people born with natural talents?','[{"key":"A","text":"They seem to outdo others without hard work."},{"key":"B","text":"They appear to know all the secrets to success."},{"key":"C","text":"They feel it only too logical to succeed."},{"key":"D","text":"They are bound to excel effortlessly."}]','A','参考答案 A，依据原文整理。首句说有天赋的人看起来不必十分努力就能表现出色；这是观察到的表象，而非必然成功。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-5-q-52','cet4-2025-06-1-section-5',1,'choice','52. What does Duckworth say about talent?','[{"key":"A","text":"It is a new concept much too overrated."},{"key":"B","text":"It proves necessary for big achievements."},{"key":"C","text":"It plays a lesser role in one’s success."},{"key":"D","text":"It is a guarantee for real success in life."}]','C','参考答案 C，依据原文整理。Duckworth 认为努力的重要性是天赋的两倍，天赋可能被高估，没有 grit 仍难以成功。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-5-q-53','cet4-2025-06-1-section-5',2,'choice','53. What does the passage say about people thinking of attaining success?','[{"key":"A","text":"They are puzzled how to present their best to the employer."},{"key":"B","text":"They are burdened by their expectation of perfection."},{"key":"C","text":"They will try hard to land a job that fits their skills best."},{"key":"D","text":"They will find themselves lacking in all the skills they need."}]','B','参考答案 B，依据原文整理。第三段说人们想到成功时会被必须掌握各种技能、每项都完美的要求压得喘不过气。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-5-q-54','cet4-2025-06-1-section-5',3,'choice','54. How does the author think grit can be helpful to us?','[{"key":"A","text":"It allows us to know what we are good at."},{"key":"B","text":"It opens our eyes to new opportunities."},{"key":"C","text":"It focuses our attention on what we do."},{"key":"D","text":"It lets us reconsider the goals to achieve."}]','D','参考答案 D，依据原文整理。第四段明确说 Grit allows us to redefine our goals，帮助人们重新考虑曾因技能不足放弃的目标。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-5-q-55','cet4-2025-06-1-section-5',4,'choice','55. What message does Duckworth try to convey in her book Grit?','[{"key":"A","text":"We should perfect ourselves to ensure success."},{"key":"B","text":"We should stay persistent even in face of failures."},{"key":"C","text":"We can never master a skill without constant practice."},{"key":"D","text":"We can never expect to reach our goals without passion."}]','B','参考答案 B，依据原文整理。末段强调持续的热情与尝试，并以 If at first you fail, then try one more time with grit 鼓励失败后坚持。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-1-1','cet4-2025-06-1',400,0,'With those born with natural talents, it feels as if they excel without really trying.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-1-2','cet4-2025-06-1',400,1,'But what about those of us who don’t have a natural talent?','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-1-3','cet4-2025-06-1',400,2,'We’ve been told all our lives that if you work hard, you too can succeed.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-1-4','cet4-2025-06-1',400,3,'But with the release of Angela Duckworth’s Grit, we are given a new key to success.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-2-1','cet4-2025-06-1',401,0,'“As much as talent counts, effort counts twice,” says Duckworth in Grit.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-2-2','cet4-2025-06-1',401,1,'She introduces a new concept that talent may be overrated, and if you want real success, what you need is grit, the perfect combination of passion and persistence.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-2-3','cet4-2025-06-1',401,2,'Even if you have natural talent, it’s nothing without grit.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-3-1','cet4-2025-06-1',402,0,'Duckworth says grit is the difference between success and failure.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-3-2','cet4-2025-06-1',402,1,'A person who has grit is more likely to succeed than a person who does not.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-3-3','cet4-2025-06-1',402,2,'When we think about attaining success — whether it’s landing that job or learning that new skill—our thoughts are immediately burdened by all the things we must first learn.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-3-4','cet4-2025-06-1',402,3,'If you want that new job, you have to learn the job skills, then the interview skills, then the dress part — and you must be perfect at all of them.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-3-5','cet4-2025-06-1',402,4,'Grit is different because it tells us that perfection isn’t the goal.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-4-1','cet4-2025-06-1',403,0,'Grit lifts the unreasonable expectations off our shoulders.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-4-2','cet4-2025-06-1',403,1,'Grit tells us that the door is open wider than we first thought possible.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-4-3','cet4-2025-06-1',403,2,'Grit allows us to redefine our goals.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-4-4','cet4-2025-06-1',403,3,'Think about it: what’s something you’ve always wanted to do, but gave up because you “don’t have the skills for it”?','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-4-5','cet4-2025-06-1',403,4,'What’s something you love but aren’t good at?','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-1','cet4-2025-06-1',404,0,'The real workings of grit are to have sustainable passion and continue to try.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-2','cet4-2025-06-1',404,1,'Effort means more than your natural ability.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-3','cet4-2025-06-1',404,2,'Even if you haven’t mastered a skill, grit tells you that you can still succeed if you can transform your passion into action.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-4','cet4-2025-06-1',404,3,'In a way, Duckworth is giving new hope to people who have shut the doors on their dreams.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-5','cet4-2025-06-1',404,4,'She is saying it is possible that you can accomplish anything.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-1-section-5-sentence-5-6','cet4-2025-06-1',404,5,'If at first you fail, then try one more time with grit.','cet4-2025-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-1-section-6','cet4-2025-06-1',5,'translation','翻译 · 汉译英','For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your answer on Answer Sheet 2.','["被誉为“杂交水稻(hybrid rice)之父”的袁隆平和他的科研团队克服重重困难，研发出了一种超级杂交水稻。这项技术获得了举世公认的巨大成功。通过这项技术的应用，水稻抗旱抗病能力更强，能适应不同的气候和土壤条件，产量可提高20%-30%。超级杂交水稻营养丰富，口感更佳。目前，这项技术已经在许多国家得到广泛应用，为全球粮食安全做出了重大贡献。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
