INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-1-1','cet4-2025-06-2',100,0,'Sir Alfred Hitchcock was an English movie director and producer.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-1-2','cet4-2025-06-2',100,1,'Famously referred to as ‘The Master of Suspense,’ Hitchcock is one of the most influential filmmakers in the history of cinema.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-1-3','cet4-2025-06-2',100,2,'He was an extraordinary director who entertained his audience with engaging and gripping suspense movies.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-2-1','cet4-2025-06-2',101,0,'His fascination with crime began at an early age when he was punished by his father who made him spend a few minutes inside a prison for his misconduct.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-2-2','cet4-2025-06-2',101,1,'Hence, his movies are symbolic of the guilt and innocence of the wrongdoer and the victim.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-2-3','cet4-2025-06-2',101,2,'He had a gift for creating stories that consisted of deceit, robbery, murder, corruption, and other criminal offences with incredible plot twists in the storyline.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-2-4','cet4-2025-06-2',101,3,'The principal characters in his movies were often ordinary people caught in unwanted and unavoidable situations.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-3-1','cet4-2025-06-2',102,0,'He was highly productive and his amazing body of work is considered fascinating by the critics.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-3-2','cet4-2025-06-2',102,1,'Most of his movies have stood the test of time and are considered to be masterpieces.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-3-3','cet4-2025-06-2',102,2,'He is also remembered by other filmmakers, for he continues to inspire them to be passionate about their work.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-2-sentence-3-4','cet4-2025-06-2',102,3,'He is also worshipped by people around the world for his entertaining and exciting stories.','cet4-2025-06-2-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-2-section-3','cet4-2025-06-2',2,'matching','长篇阅读（36–45）· Is juicing actually good for you?','将每条陈述与对应段落匹配；一个段落可以重复使用。','["[A] Freshly juiced fruit has become a basic dietary item—especially for busy, health-conscious consumers who can save time on making (and perhaps even chewing) their food without missing out on nutrients. Fruit juice also has been linked to claims that it can help you both lose weight and stay healthy. All of which, of course, has made it highly profitable. The global fruit and vegetable juices market was valued at $154 billion in 2016 and is expected to grow.","[B] But is juicing really as healthy as we think? Most foods containing fructose—a naturally occurring sugar found in all fruits and fruit juices—don’t seem to have harmful effects as long as they’re not contributing to excess daily calories. This is because the fibre found in whole fruits is intact, and the sugar is contained within the fruit’s cells. It takes our digestive system a while to break these cells down and for fructose to enter the bloodstream.","[C] But this is not the case with fruit juice. Unlike whole fruit, fruit juice has most of the fibre removed. This is why the fructose in fruit juices counts as ‘free sugars’—which also include honey and the sugars added to foods. It’s recommended by the World Health Organisation that adults have no more than 30g of added sugar, the equivalent of 150ml of fruit juice, per day. The problem is that, with the fibre removed, fruit juice’s fructose is absorbed more quickly. Sudden increases in blood sugar cause the release of insulin (胰岛素) to bring it back down to a stable level. Over time, this mechanism can wear out, increasing the risk of developing type 2 diabetes. In 2013, researchers analysed the health data of 100,000 people collected between 1986 and 2009 and found that fruit juice consumption was linked with increased risk of type 2 diabetes. Another study found a relationship between fruit juice and type 2 diabetes after following the diets and diabetes status of more than 70,000 nurses over 18 years. The researchers explain that the possible reason for this may partly have been the lack of the other components found in whole fruit, like fibre.","[D] Juices containing vegetables can provide more nutrients and less sugar than juices made up of just fruit—but they still lack valuable fibre. Diets high in fibre have been linked to a lower risk of developing heart disease, stroke, high blood pressure and diabetes, and it’s recommended adults consume 30g per day.","[E] Aside from the link to type 2 diabetes, many studies agree that fruit juice is harmful if it contributes to an excess in calories. In an analysis of 155 studies, John Sievenpiper, associate professor at the University of Toronto’s Department of Nutritional Sciences, set out to understand if the associations between sugary soft drinks and health—including risk of diabetes and heart disease—were applicable to the food and drink we generally consume as part of a healthy diet. He compared studies looking into the effects of fructose-containing sugars with control diets free from or lower in these sugars. His aim? To isolate the effects of consuming too many calories from the effects of foods containing different sugars.","[F] He found negative effects on blood sugar and insulin levels when food provided excess calories from sugars, including fruit juice. However, when the calories weren’t in excess overall, there were some advantages to consuming whole fruit—and even fruit juice. Sievenpiper concludes that the recommended 150ml of fruit juice per day, which is an average serving, is reasonable. The paper concluded that foods containing fructose may have some small benefits for long-term blood sugar control when they don’t lead to over-consumption of calories. But when they do lead to too many calories, they risk raising blood sugar and insulin levels.","[G] So while we know that fruit juice can cause diabetes if it’s part of a diet that has more calories overall, it’s less clear how juice affects the long-term health of those who aren’t overweight. But we have a higher risk of consuming more than the recommended daily number of calories (around 2,000 for women and 2,500 for men) on the days we drink juice, according to research. Numerous studies have shown that drinking fruit juice doesn’t make us consume any less of other foods throughout the day.","[H] As it is easy to consume large amounts of fruit juice quite quickly, extra calories are taken in. And extra calories can contribute to weight gain. One way we can improve the effects of fruit juice on our health is making sure we select ripe fruit to retain as much of its goodness as possible, according to Roger Clemens, professor of pharmaceutical ( 药物的) sciences at the University of Southern California.","[I] Another reason for fruit juice’s recent popularity is the argument that it can help to remove poisonous or harmful substances from the body. However, “the whole concept of a juice diet helping to remove poisonous or harmful substances from the body is completely false,” says Clemens. “We consume compounds every day that may be poisonous and our bodies do a wonderful job of removing and eliminating anything harmful from our bodies.”","[J] And juice isn’t a cure-all for getting your nutrients, either. “There are a lot of nutrients contained in the parts of the fruits, such as in apple skins, that are excluded when you juice them,” says Heather Ferris, a professor of medicine. “You end up with sugary water with some vitamins.”","[K] Plus, she adds, it’s not an ideal way to reach the advised‘five a day’. “People try to get five servings of fruit and vegetables per day and don’t realise this isn’t just about getting vitamins,” she says. “It’s also about reducing the amount of grain carbs (碳水化合物) and protein and fats in our diet, and increasing fibre.” So while fruit juice is better than no fruit at all, there are limits. It particularly comes with risks when we consume more than 150ml of free sugars per day, or when it puts us over our recommended calorie intake. It provides us with vitamins—but fruit juice is far from a quick fix."]','["Freshly juiced fruit has become a basic dietary item—especially for busy, health-conscious consumers who can save time on making (and perhaps even chewing) their food without missing out on nutrients. Fruit juice also has been linked to claims that it can help you both lose weight and stay healthy. All of which, of course, has made it highly profitable. The global fruit and vegetable juices market was valued at $154 billion in 2016 and is expected to grow.","But is juicing really as healthy as we think? Most foods containing fructose—a naturally occurring sugar found in all fruits and fruit juices—don’t seem to have harmful effects as long as they’re not contributing to excess daily calories. This is because the fibre found in whole fruits is intact, and the sugar is contained within the fruit’s cells. It takes our digestive system a while to break these cells down and for fructose to enter the bloodstream.","But this is not the case with fruit juice. Unlike whole fruit, fruit juice has most of the fibre removed. This is why the fructose in fruit juices counts as ‘free sugars’—which also include honey and the sugars added to foods. It’s recommended by the World Health Organisation that adults have no more than 30g of added sugar, the equivalent of 150ml of fruit juice, per day. The problem is that, with the fibre removed, fruit juice’s fructose is absorbed more quickly. Sudden increases in blood sugar cause the release of insulin (胰岛素) to bring it back down to a stable level. Over time, this mechanism can wear out, increasing the risk of developing type 2 diabetes. In 2013, researchers analysed the health data of 100,000 people collected between 1986 and 2009 and found that fruit juice consumption was linked with increased risk of type 2 diabetes. Another study found a relationship between fruit juice and type 2 diabetes after following the diets and diabetes status of more than 70,000 nurses over 18 years. The researchers explain that the possible reason for this may partly have been the lack of the other components found in whole fruit, like fibre.","Juices containing vegetables can provide more nutrients and less sugar than juices made up of just fruit—but they still lack valuable fibre. Diets high in fibre have been linked to a lower risk of developing heart disease, stroke, high blood pressure and diabetes, and it’s recommended adults consume 30g per day.","Aside from the link to type 2 diabetes, many studies agree that fruit juice is harmful if it contributes to an excess in calories. In an analysis of 155 studies, John Sievenpiper, associate professor at the University of Toronto’s Department of Nutritional Sciences, set out to understand if the associations between sugary soft drinks and health—including risk of diabetes and heart disease—were applicable to the food and drink we generally consume as part of a healthy diet. He compared studies looking into the effects of fructose-containing sugars with control diets free from or lower in these sugars. His aim? To isolate the effects of consuming too many calories from the effects of foods containing different sugars.","He found negative effects on blood sugar and insulin levels when food provided excess calories from sugars, including fruit juice. However, when the calories weren’t in excess overall, there were some advantages to consuming whole fruit—and even fruit juice. Sievenpiper concludes that the recommended 150ml of fruit juice per day, which is an average serving, is reasonable. The paper concluded that foods containing fructose may have some small benefits for long-term blood sugar control when they don’t lead to over-consumption of calories. But when they do lead to too many calories, they risk raising blood sugar and insulin levels.","So while we know that fruit juice can cause diabetes if it’s part of a diet that has more calories overall, it’s less clear how juice affects the long-term health of those who aren’t overweight. But we have a higher risk of consuming more than the recommended daily number of calories (around 2,000 for women and 2,500 for men) on the days we drink juice, according to research. Numerous studies have shown that drinking fruit juice doesn’t make us consume any less of other foods throughout the day.","As it is easy to consume large amounts of fruit juice quite quickly, extra calories are taken in. And extra calories can contribute to weight gain. One way we can improve the effects of fruit juice on our health is making sure we select ripe fruit to retain as much of its goodness as possible, according to Roger Clemens, professor of pharmaceutical ( 药物的) sciences at the University of Southern California.","Another reason for fruit juice’s recent popularity is the argument that it can help to remove poisonous or harmful substances from the body. However, “the whole concept of a juice diet helping to remove poisonous or harmful substances from the body is completely false,” says Clemens. “We consume compounds every day that may be poisonous and our bodies do a wonderful job of removing and eliminating anything harmful from our bodies.”","And juice isn’t a cure-all for getting your nutrients, either. “There are a lot of nutrients contained in the parts of the fruits, such as in apple skins, that are excluded when you juice them,” says Heather Ferris, a professor of medicine. “You end up with sugary water with some vitamins.”","Plus, she adds, it’s not an ideal way to reach the advised‘five a day’. “People try to get five servings of fruit and vegetables per day and don’t realise this isn’t just about getting vitamins,” she says. “It’s also about reducing the amount of grain carbs (碳水化合物) and protein and fats in our diet, and increasing fibre.” So while fruit juice is better than no fruit at all, there are limits. It particularly comes with risks when we consume more than 150ml of free sugars per day, or when it puts us over our recommended calorie intake. It provides us with vitamins—but fruit juice is far from a quick fix."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-36','cet4-2025-06-2-section-3',0,'choice','36. Fruit juice is different from whole fruit in that it contains much less fibre.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','C','参考答案 C，依据原文整理。C 段开头明确对比完整水果与果汁，指出果汁的大部分纤维已被去除。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-37','cet4-2025-06-2-section-3',1,'choice','37. Some people believe a juice diet helps to rid our body of harmful or poisonous substances.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','I','参考答案 I，依据原文整理。I 段介绍认为果汁饮食能够清除体内有害或有毒物质的观点，随后引用专家反驳。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-38','cet4-2025-06-2-section-3',2,'choice','38. A lot of research comes to the same conclusion that fruit juice does harm to the human body when it leads to surplus calories.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','E','参考答案 E，依据原文整理。E 段开头说许多研究认为果汁在造成热量过剩时有害，并介绍对 155 项研究的分析。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-39','cet4-2025-06-2-section-3',3,'choice','39. The claimed health benefits of fruit and vegetable juices have rendered the industry very profitable.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','A','参考答案 A，依据原文整理。A 段将果汁被宣称的减重、健康益处与该行业的高利润联系起来。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-40','cet4-2025-06-2-section-3',4,'choice','40. To increase the benefits of fruit juice to our health, we’d better choose ripe fruit to make juice.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','H','参考答案 H，依据原文整理。H 段引用专家建议，选择成熟水果可以尽可能保留其有益成分。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-41','cet4-2025-06-2-section-3',5,'choice','41. Diets containing large amounts of fibre reduce the risk of heart disease, diabetes and other health hazards.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','D','参考答案 D，依据原文整理。D 段列出高纤维饮食与较低的心脏病、中风、高血压和糖尿病风险之间的联系。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-42','cet4-2025-06-2-section-3',6,'choice','42. According to a research paper, drinking fruit juice is beneficial on condition that it is consumed in reasonable amounts.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','F','参考答案 F，依据原文整理。F 段说在总热量不过剩时，完整水果甚至果汁可能具有一些益处，并指出每日 150 毫升属于合理量。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-43','cet4-2025-06-2-section-3',7,'choice','43. One expert claims that juicing wastes a lot of nutrients contained in fruits.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','J','参考答案 J，依据原文整理。J 段指出果皮等部位的许多营养成分在榨汁时被排除，引用专家说明榨汁造成的损失。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-44','cet4-2025-06-2-section-3',8,'choice','44. It takes some time for fruit’s cells to be digested and for fructose to be absorbed.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','B','参考答案 B，依据原文整理。B 段说消化系统需要时间分解完整水果的细胞，果糖随后才能进入血液。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-3-q-45','cet4-2025-06-2-section-3',9,'choice','45. A lot of research has demonstrated that drinking fruit juice does not reduce our daily consumption of other foods.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"}]','G','参考答案 G，依据原文整理。G 段末句明确说大量研究表明饮用果汁不会让人减少当天其他食物的摄入。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-1-1','cet4-2025-06-2',200,0,'Freshly juiced fruit has become a basic dietary item—especially for busy, health-conscious consumers who can save time on making (and perhaps even chewing) their food without missing out on nutrients.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-1-2','cet4-2025-06-2',200,1,'Fruit juice also has been linked to claims that it can help you both lose weight and stay healthy.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-1-3','cet4-2025-06-2',200,2,'All of which, of course, has made it highly profitable.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-1-4','cet4-2025-06-2',200,3,'The global fruit and vegetable juices market was valued at $154 billion in 2016 and is expected to grow.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-2-1','cet4-2025-06-2',201,0,'But is juicing really as healthy as we think?','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-2-2','cet4-2025-06-2',201,1,'Most foods containing fructose—a naturally occurring sugar found in all fruits and fruit juices—don’t seem to have harmful effects as long as they’re not contributing to excess daily calories.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-2-3','cet4-2025-06-2',201,2,'This is because the fibre found in whole fruits is intact, and the sugar is contained within the fruit’s cells.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-2-4','cet4-2025-06-2',201,3,'It takes our digestive system a while to break these cells down and for fructose to enter the bloodstream.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-1','cet4-2025-06-2',202,0,'But this is not the case with fruit juice.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-2','cet4-2025-06-2',202,1,'Unlike whole fruit, fruit juice has most of the fibre removed.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-3','cet4-2025-06-2',202,2,'This is why the fructose in fruit juices counts as ‘free sugars’—which also include honey and the sugars added to foods.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-4','cet4-2025-06-2',202,3,'It’s recommended by the World Health Organisation that adults have no more than 30g of added sugar, the equivalent of 150ml of fruit juice, per day.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-5','cet4-2025-06-2',202,4,'The problem is that, with the fibre removed, fruit juice’s fructose is absorbed more quickly.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-6','cet4-2025-06-2',202,5,'Sudden increases in blood sugar cause the release of insulin (胰岛素) to bring it back down to a stable level.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-7','cet4-2025-06-2',202,6,'Over time, this mechanism can wear out, increasing the risk of developing type 2 diabetes.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-8','cet4-2025-06-2',202,7,'In 2013, researchers analysed the health data of 100,000 people collected between 1986 and 2009 and found that fruit juice consumption was linked with increased risk of type 2 diabetes.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-9','cet4-2025-06-2',202,8,'Another study found a relationship between fruit juice and type 2 diabetes after following the diets and diabetes status of more than 70,000 nurses over 18 years.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-3-10','cet4-2025-06-2',202,9,'The researchers explain that the possible reason for this may partly have been the lack of the other components found in whole fruit, like fibre.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-4-1','cet4-2025-06-2',203,0,'Juices containing vegetables can provide more nutrients and less sugar than juices made up of just fruit—but they still lack valuable fibre.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-4-2','cet4-2025-06-2',203,1,'Diets high in fibre have been linked to a lower risk of developing heart disease, stroke, high blood pressure and diabetes, and it’s recommended adults consume 30g per day.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-5-1','cet4-2025-06-2',204,0,'Aside from the link to type 2 diabetes, many studies agree that fruit juice is harmful if it contributes to an excess in calories.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-5-2','cet4-2025-06-2',204,1,'In an analysis of 155 studies, John Sievenpiper, associate professor at the University of Toronto’s Department of Nutritional Sciences, set out to understand if the associations between sugary soft drinks and health—including risk of diabetes and heart disease—were applicable to the food and drink we generally consume as part of a healthy diet.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-5-3','cet4-2025-06-2',204,2,'He compared studies looking into the effects of fructose-containing sugars with control diets free from or lower in these sugars.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-5-4','cet4-2025-06-2',204,3,'His aim?','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-5-5','cet4-2025-06-2',204,4,'To isolate the effects of consuming too many calories from the effects of foods containing different sugars.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-6-1','cet4-2025-06-2',205,0,'He found negative effects on blood sugar and insulin levels when food provided excess calories from sugars, including fruit juice.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-6-2','cet4-2025-06-2',205,1,'However, when the calories weren’t in excess overall, there were some advantages to consuming whole fruit—and even fruit juice.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-6-3','cet4-2025-06-2',205,2,'Sievenpiper concludes that the recommended 150ml of fruit juice per day, which is an average serving, is reasonable.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-6-4','cet4-2025-06-2',205,3,'The paper concluded that foods containing fructose may have some small benefits for long-term blood sugar control when they don’t lead to over-consumption of calories.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-6-5','cet4-2025-06-2',205,4,'But when they do lead to too many calories, they risk raising blood sugar and insulin levels.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-7-1','cet4-2025-06-2',206,0,'So while we know that fruit juice can cause diabetes if it’s part of a diet that has more calories overall, it’s less clear how juice affects the long-term health of those who aren’t overweight.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-7-2','cet4-2025-06-2',206,1,'But we have a higher risk of consuming more than the recommended daily number of calories (around 2,000 for women and 2,500 for men) on the days we drink juice, according to research.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-7-3','cet4-2025-06-2',206,2,'Numerous studies have shown that drinking fruit juice doesn’t make us consume any less of other foods throughout the day.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-8-1','cet4-2025-06-2',207,0,'As it is easy to consume large amounts of fruit juice quite quickly, extra calories are taken in.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-8-2','cet4-2025-06-2',207,1,'And extra calories can contribute to weight gain.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-8-3','cet4-2025-06-2',207,2,'One way we can improve the effects of fruit juice on our health is making sure we select ripe fruit to retain as much of its goodness as possible, according to Roger Clemens, professor of pharmaceutical ( 药物的) sciences at the University of Southern California.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-9-1','cet4-2025-06-2',208,0,'Another reason for fruit juice’s recent popularity is the argument that it can help to remove poisonous or harmful substances from the body.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-9-2','cet4-2025-06-2',208,1,'However, “the whole concept of a juice diet helping to remove poisonous or harmful substances from the body is completely false,” says Clemens.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-9-3','cet4-2025-06-2',208,2,'“We consume compounds every day that may be poisonous and our bodies do a wonderful job of removing and eliminating anything harmful from our bodies.”','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-10-1','cet4-2025-06-2',209,0,'And juice isn’t a cure-all for getting your nutrients, either.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-10-2','cet4-2025-06-2',209,1,'“There are a lot of nutrients contained in the parts of the fruits, such as in apple skins, that are excluded when you juice them,” says Heather Ferris, a professor of medicine.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-10-3','cet4-2025-06-2',209,2,'“You end up with sugary water with some vitamins.”','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-1','cet4-2025-06-2',210,0,'Plus, she adds, it’s not an ideal way to reach the advised‘five a day’.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-2','cet4-2025-06-2',210,1,'“People try to get five servings of fruit and vegetables per day and don’t realise this isn’t just about getting vitamins,” she says.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-3','cet4-2025-06-2',210,2,'“It’s also about reducing the amount of grain carbs (碳水化合物) and protein and fats in our diet, and increasing fibre.”','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-4','cet4-2025-06-2',210,3,'So while fruit juice is better than no fruit at all, there are limits.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-5','cet4-2025-06-2',210,4,'It particularly comes with risks when we consume more than 150ml of free sugars per day, or when it puts us over our recommended calorie intake.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-3-sentence-11-6','cet4-2025-06-2',210,5,'It provides us with vitamins—but fruit juice is far from a quick fix.','cet4-2025-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-2-section-4','cet4-2025-06-2',3,'reading','仔细阅读 · Passage One（46–50）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["We all take a little extra effort to look nice for special occasions. But most of us have conflicting feelings about dressing up and feel guilty about taking the time to focus on clothes. Science now suggests the right dress may give ourselves the extra edge in our professional and personal lives. We hear sayings like “dress for the job you want; not the job you have”. Most people don’t really believe in them, but research into the impact of clothes on behavior now suggests that there may actually be a grain of truth in these sayings. Science says that the clothes we wear affect our behavior, our mood and even the way we interact with others because of the symbolic meaning that we assign to different types of clothing.","We consider some clothes to be powerful, some to be fun, and so on. We even evaluate people whom we have just met based on their clothes. We also evaluate ourselves based on what we are wearing because of the way they make us feel. This means that the experience of wearing something affects our attitudes and our choice of behavior.","There’s a reason tailored jackets are associated with being ‘dressed for success’. It seems that wearing formal office wear puts us in the right frame of mind to conduct business. Wearing power clothing makes us feel more confident and even increases hormones needed for—displaying dominance. This in turn helps us become better negotiators and abstract thinkers.","While a good suit works wonders for our performance in the boardroom, wearing formal wear isn’t a great idea when we want to socialize. Studies have found that people tend to be less open and less able to relax when they wear formal clothes.","On the other hand, a casual dress helps us become more friendly and creative. These findings support the idea of wearing business casuals on a Friday; since colleagues are most likely to take out time to socialize on the last work day of the week. I mean, who wants to hang out with people in their suits?"]','["We all take a little extra effort to look nice for special occasions. But most of us have conflicting feelings about dressing up and feel guilty about taking the time to focus on clothes. Science now suggests the right dress may give ourselves the extra edge in our professional and personal lives. We hear sayings like “dress for the job you want; not the job you have”. Most people don’t really believe in them, but research into the impact of clothes on behavior now suggests that there may actually be a grain of truth in these sayings. Science says that the clothes we wear affect our behavior, our mood and even the way we interact with others because of the symbolic meaning that we assign to different types of clothing.","We consider some clothes to be powerful, some to be fun, and so on. We even evaluate people whom we have just met based on their clothes. We also evaluate ourselves based on what we are wearing because of the way they make us feel. This means that the experience of wearing something affects our attitudes and our choice of behavior.","There’s a reason tailored jackets are associated with being ‘dressed for success’. It seems that wearing formal office wear puts us in the right frame of mind to conduct business. Wearing power clothing makes us feel more confident and even increases hormones needed for—displaying dominance. This in turn helps us become better negotiators and abstract thinkers.","While a good suit works wonders for our performance in the boardroom, wearing formal wear isn’t a great idea when we want to socialize. Studies have found that people tend to be less open and less able to relax when they wear formal clothes.","On the other hand, a casual dress helps us become more friendly and creative. These findings support the idea of wearing business casuals on a Friday; since colleagues are most likely to take out time to socialize on the last work day of the week. I mean, who wants to hang out with people in their suits?"]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-4-q-46','cet4-2025-06-2-section-4',0,'choice','46. What does science suggest the right dress may do?','[{"key":"A","text":"Add to our advantage in work and life."},{"key":"B","text":"Enable us to look a lot more attractive."},{"key":"C","text":"Help us to enjoy a fuller personal life."},{"key":"D","text":"Provide extra energy for what we do."}]','A','参考答案 A，依据原文整理。首段指出合适的服装可能在职业与个人生活中为人们带来额外优势。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-4-q-47','cet4-2025-06-2-section-4',1,'choice','47. Why does science say the clothes one wears may affect their interaction with others?','[{"key":"A","text":"Clothes usually represent one’s social and economic status."},{"key":"B","text":"Clothes largely determine one’s likability by people around."},{"key":"C","text":"Different types of clothing markedly reflect different personalities."},{"key":"D","text":"Different types of clothing convey different messages symbolically."}]','D','参考答案 D，依据原文整理。首段末尾说不同类型的服装被赋予象征意义，这会影响行为、情绪及与他人的互动。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-4-q-48','cet4-2025-06-2-section-4',2,'choice','48. How do the clothes we wear sway our evaluation of ourselves?','[{"key":"A","text":"By exerting an effect on our power of judgment."},{"key":"B","text":"By impacting how we feel about ourselves."},{"key":"C","text":"By affecting what we take as the basis for assessment."},{"key":"D","text":"By influencing our interpretation of symbolic messages."}]','B','参考答案 B，依据原文整理。第二段指出人们会依据着装评估自己，因为服装会改变自己的感受。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-4-q-49','cet4-2025-06-2-section-4',3,'choice','49. Why does the author say tailored jackets are associated with being ‘dressed for success’?','[{"key":"A","text":"They are necessary for formal business dealings."},{"key":"B","text":"They may help people concentrate on their business."},{"key":"C","text":"They are vital to keeping a dominant position in business transactions."},{"key":"D","text":"They may enable people to have the right mentality for doing business."}]','D','参考答案 D，依据原文整理。第三段明确说正式办公服装使人进入适合开展业务的心理状态。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-4-q-50','cet4-2025-06-2-section-4',4,'choice','50. What are people advised to do when they want to socialize?','[{"key":"A","text":"Focus on clothing."},{"key":"B","text":"Wear a good suit."},{"key":"C","text":"Dress casually."},{"key":"D","text":"Look unusual."}]','C','参考答案 C，依据原文整理。末段说休闲服装让人更友善、富有创造力，适合与同事社交。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
