INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-1-5','cet4-2025-06-2',300,4,'Most people don’t really believe in them, but research into the impact of clothes on behavior now suggests that there may actually be a grain of truth in these sayings.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-1-6','cet4-2025-06-2',300,5,'Science says that the clothes we wear affect our behavior, our mood and even the way we interact with others because of the symbolic meaning that we assign to different types of clothing.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-2-1','cet4-2025-06-2',301,0,'We consider some clothes to be powerful, some to be fun, and so on.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-2-2','cet4-2025-06-2',301,1,'We even evaluate people whom we have just met based on their clothes.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-2-3','cet4-2025-06-2',301,2,'We also evaluate ourselves based on what we are wearing because of the way they make us feel.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-2-4','cet4-2025-06-2',301,3,'This means that the experience of wearing something affects our attitudes and our choice of behavior.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-3-1','cet4-2025-06-2',302,0,'There’s a reason tailored jackets are associated with being ‘dressed for success’.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-3-2','cet4-2025-06-2',302,1,'It seems that wearing formal office wear puts us in the right frame of mind to conduct business.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-3-3','cet4-2025-06-2',302,2,'Wearing power clothing makes us feel more confident and even increases hormones needed for—displaying dominance.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-3-4','cet4-2025-06-2',302,3,'This in turn helps us become better negotiators and abstract thinkers.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-4-1','cet4-2025-06-2',303,0,'While a good suit works wonders for our performance in the boardroom, wearing formal wear isn’t a great idea when we want to socialize.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-4-2','cet4-2025-06-2',303,1,'Studies have found that people tend to be less open and less able to relax when they wear formal clothes.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-5-1','cet4-2025-06-2',304,0,'On the other hand, a casual dress helps us become more friendly and creative.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-5-2','cet4-2025-06-2',304,1,'These findings support the idea of wearing business casuals on a Friday; since colleagues are most likely to take out time to socialize on the last work day of the week.','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-06-2-section-4-sentence-5-3','cet4-2025-06-2',304,2,'I mean, who wants to hang out with people in their suits?','cet4-2025-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2025-06-2-section-5','cet4-2025-06-2',4,'reading','仔细阅读 · Passage Two（51–55）','There are 2 passages in this section. Each passage is followed by some questions or unfinished statements. For each of them there are four choices marked A), B), C) and D). You should decide on the best choice and mark the corresponding letter on Answer Sheet 2 with a single line through the centre.','["With the rise of pop music, jazz, and electronic music, both opera and classical music started to fade away from the public eye. Some people are beginning to wonder whether opera and classical music are still relevant to the modern world of music. Granted, you will not typically see today’s teenagers lending their ears to Bach anytime soon, but there are some major indicators that both opera and classical music are now still quite alive.","The most major indicator of classical music’s importance in society today is the fact that much of the popular music that is currently being produced uses similar beats, harmonies, and melodies (旋律) as those that were used in some of classical music’s best works. Even so, it can be difficult for those who do not study music theory to see this as an indicator, since it is subtle and just shows the impact symphonic (交响乐的) orchestras have had on society’s taste in music.","A better example for the relevance of opera and classical music can be seen in the invention of the rock opera. Opera, in its simplest definition, is telling a story using music as its form. The art of telling a story using music has not faded in the least bit. In fact, sometimes actual orchestras are used for major parts of the opera itself. Some of the world’s greatest hits have been parts of rock operas.","Fans of classical music can also tell you that there are few types of music that are more expressive. So, it should come as no surprise to anyone that classical music pieces are still used as background music in modern movies. Symphonic orchestra compositions have also been created solely for the purpose of being included in major motion pictures. These are often very well received amongst mainstream music fans.","Classical music and opera are the very foundation of what our modern music is based upon. Considering the huge impact they have had on our current society, it is without doubt that we can expect them to continue to remain important for centuries to come."]','["With the rise of pop music, jazz, and electronic music, both opera and classical music started to fade away from the public eye. Some people are beginning to wonder whether opera and classical music are still relevant to the modern world of music. Granted, you will not typically see today’s teenagers lending their ears to Bach anytime soon, but there are some major indicators that both opera and classical music are now still quite alive.","The most major indicator of classical music’s importance in society today is the fact that much of the popular music that is currently being produced uses similar beats, harmonies, and melodies (旋律) as those that were used in some of classical music’s best works. Even so, it can be difficult for those who do not study music theory to see this as an indicator, since it is subtle and just shows the impact symphonic (交响乐的) orchestras have had on society’s taste in music.","A better example for the relevance of opera and classical music can be seen in the invention of the rock opera. Opera, in its simplest definition, is telling a story using music as its form. The art of telling a story using music has not faded in the least bit. In fact, sometimes actual orchestras are used for major parts of the opera itself. Some of the world’s greatest hits have been parts of rock operas.","Fans of classical music can also tell you that there are few types of music that are more expressive. So, it should come as no surprise to anyone that classical music pieces are still used as background music in modern movies. Symphonic orchestra compositions have also been created solely for the purpose of being included in major motion pictures. These are often very well received amongst mainstream music fans.","Classical music and opera are the very foundation of what our modern music is based upon. Considering the huge impact they have had on our current society, it is without doubt that we can expect them to continue to remain important for centuries to come."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-5-q-51','cet4-2025-06-2-section-5',0,'choice','51. What does the author think of classical music and opera in today’s world?','[{"key":"A","text":"They still make their presence felt."},{"key":"B","text":"They have given way to electronic music."},{"key":"C","text":"They will not fade away from the public eye."},{"key":"D","text":"They are no longer relevant to teenagers’ lives."}]','A','参考答案 A，依据原文整理。首段指出仍有许多迹象表明歌剧和古典音乐至今保持着活力与影响力。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-5-q-52','cet4-2025-06-2-section-5',1,'choice','52. What do we learn about much of the popular music currently produced?','[{"key":"A","text":"It can be difficult for many classical music fans to appreciate."},{"key":"B","text":"It can be seen as an indicator of refinement on classical music."},{"key":"C","text":"It caters to society’s taste in music in a more subtle way than classical music."},{"key":"D","text":"It contains elements similar to those in some masterpieces of classical music."}]','D','参考答案 D，依据原文整理。第二段说许多当代流行音乐使用了与古典杰作相似的节拍、和声与旋律。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-5-q-53','cet4-2025-06-2-section-5',2,'choice','53. Why does the author mention the invention of the rock opera?','[{"key":"A","text":"To illustrate how to tell a story using music."},{"key":"B","text":"To present the simplest definition of opera."},{"key":"C","text":"To show the relevance of opera and classical music."},{"key":"D","text":"To justify the necessity of using orchestras in opera."}]','C','参考答案 C，依据原文整理。第三段开头明确用摇滚歌剧作为歌剧和古典音乐仍与当代相关的例子。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-5-q-54','cet4-2025-06-2-section-5',3,'choice','54. Why are classical music pieces still used as background music in modern movies?','[{"key":"A","text":"There are few types of music for movie producers to choose from."},{"key":"B","text":"They are considered to be the most expressive type of music."},{"key":"C","text":"They are well received by movie fans from all over the world."},{"key":"D","text":"They are essential for movies to become the world’s greatest hits."}]','B','参考答案 B，依据原文整理。第四段说少有其他音乐类型更富表现力，因此古典音乐仍被用于现代电影配乐。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-2-section-5-q-55','cet4-2025-06-2-section-5',4,'choice','55. What do we learn about our modern music?','[{"key":"A","text":"It could not have come into being without classical music and opera as its foundation."},{"key":"B","text":"It cannot outcompete classical music and opera in its impact on our current society."},{"key":"C","text":"It will not enjoy as much popularity as classical music and opera among music fans."},{"key":"D","text":"It might not be able to rival classical music and opera in importance for centuries to come."}]','A','参考答案 A，依据原文整理。末段明确指出古典音乐与歌剧是现代音乐赖以建立的基础。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
