INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-2-sentence-3-5','cet4-2026-06-1',102,4,'However, it does not take into account unemployment, pollution, health, life expectancy, or free time.','cet4-2026-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-2-sentence-4-1','cet4-2026-06-1',103,0,'After exhausting debate and analysis of the average income, historians have agreed to disagree on whether there was rapid or slow economic growth during the Industrial Revolution.','cet4-2026-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-2-sentence-4-2','cet4-2026-06-1',103,1,'Instead, they have decided to interpret how the Industrial Revolution was affected by other events.','cet4-2026-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-2-sentence-4-3','cet4-2026-06-1',103,2,'They have determined that the Industrial Revolution had an overall positive effect , but it quite possibly was neutralized by negative events such as wars, high taxes, and rapid population growth.','cet4-2026-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-1-section-3','cet4-2026-06-1',2,'matching','长篇阅读（36–45）· The Star Quality of New Zealand’s Great Barrier Island','将每条陈述与对应段落匹配；一个段落可以重复使用。','["[A] I was glad I had such terrible jetlag. Wide awake at 3:30 am with our nine-year-old daughter on our lodge balcony, I stared for hours at the most incredible night sky I’ve ever seen before the dawn slowly started to rub out the stars on the horizon and the multiple shooting stars faded away.","[B] We were going to my wife’s big family reunion in Auckland, New Zealand, but when we found out that Great Barrier Island, just off the coast, had been recently awarded Dark Sky Sanctuary status—a typically remote area that has an “exceptional or distinguished quality of starry nights”—we thought it would be the perfect place to relax before our busy schedule. It’s the first island and only the fourth location in the world to achieve this status.","[C] After a 28-hour flight with two travel-sick children, our hearts sank when we saw the tiny twin engine 10-seater that was to take us the 90 km across the Hauraki Gulf to Great Barrier Island. But we needn’t have worried. Whether it was the gravity force of the plane climbing or the noise of the engine, it put our three-year-old daughter instantly to sleep until we bumped down on the grass at Claris Airport. Our first empty sick bag against all the odds... Things were looking up.","[D] Great Barrier Island has no public facilities and the 950 people living there (though only about half permanently) rely on solar and wind energy, and bottled gas for cooking. There are no streetlights. There are no cash machines or banks. The police force comprises a husband and wife, and there’s one postman. It’s not just the lack of light but the lack of noise that’s so delightful on this unique and gorgeous scene. It was first discovered by East Polynesians about 700 years ago and the Maori name for the island is Aotea. Captain Cook gave the island its European name, because it acts as a barrier between the Pacific and the Hauraki Gulf.","[E] The climate here is subtropical (亚热带的) like Auckland’s. The island boasts a beautiful wilderness with dense forests, glorious, unspoilt sandy beaches and plenty of bays and a few mountainous areas where there are good walking tracks among the wetlands and valleys. You can birdwatch, dive, surf and boat. The best beaches are on the eastern side of the island where the surf is better, too. The sheltered western side is where you''ll find the best diving and boating. Lots of people come here for the fantastic fishing spots around the island. Like a lot of spots in New Zealand, there are whale-watching trips and you might just catch sight of sharks.","[F] It’s rare to find an island that really does feel undiscovered—but this is it. When one of my wife’s relations, who comes here regularly, found out that we’d been there, he whispered to us, only half-joking: “Shh—don’t tell anyone!” The locals are a relaxed and friendly bunch—a lot of them told us that it’s like what Waiheke Island (now in effect a suburb of Auckland) was in the 1970s when it was a commune of artists and people wanting to escape the city.","[G] Our guide for some of our stay was the inestimable Hilde Hoven, a Dark Sky ambassador who runs Good Heavens with Deborah Kilgallon and Orla Cumisky. They bring their Dobsonian telescope and beanbags (it’s hard work staring up wide-eyed in wonder without neck support) and, our elder daughter was glad to hear, hot chocolate to wherever you are on the island. “It’s odd but when the light readings were done,” said Hilde, explaining how the island was awarded its special status, “they found there was more light pollution on the northern side coming from Fiji, which is about 3,000 km away, than Auckland to the south. It’s pretty dark!”","[H] Beginning their astronomical PowerPoint demonstration using a green laser pointer, Hilde and Orla showed us the Messier 4 spherical cluster (星团) with white dwarf stars (白矮星), Saturn and its rings, the Southern Cross and the Milky Way, which stretched across the sky. Our daughter was especially taken with Hilde’s narrating of the Maori myth of Maui’s fish hook to explain the shape of Scorpius. In the fable, Maui hauled the North Island of New Zealand from the bottom of the ocean with his hook.","[I] We stayed at Mount St Paul’s Estate, a luxurious lodge run by the friendly Chris and Teara, both from Canada. Teara used to be a chef at the Langham in Auckland and so dinner, eaten around a huge circular table (made of one of the most ancient trees in the world), was every bit as mouth-watering as you''d expect. Eating pancakes on the balcony overlooking the unspoilt white sandy beach was a great way to start the day.","[J] Another highlight was an hour-long walk to Kaitoke hot pools in the centre of the island, through wetlands and a forest, where we whiled away a good hour sitting in the pools shaded from the heat by layers of delicate umbrella-like plants.","[K] We also loved visiting the potter (陶艺家) Sarah Harrison, who showed us round her studio at Shoal Bay harbour, and her many pots and jugs, plates and bowls and colourful mosaics (马赛克). In her work, she also uses a lot of materials found on the beach. Our elder daughter loved the gorgeous hidden pool at Medlands beach where the water is separated from the sea in a private rock pool. Other high points were the ancient pohutukawa trees and the incredible views of Okiwi Basin and Whangapoua beach from the top of Windy Canyon, just a 10-minute hike through a narrow valley up some steep wooden steps on the eastern side of the island.","[L] Apparently the island council turned down famous musician Paul McCartney’s application to buy a property at Great Barrier Island because of the unwelcome attention he would have brought. You can see why he wanted to come here; equally, the island knows exactly what kind of star watching it prefers."]','["I was glad I had such terrible jetlag. Wide awake at 3:30 am with our nine-year-old daughter on our lodge balcony, I stared for hours at the most incredible night sky I’ve ever seen before the dawn slowly started to rub out the stars on the horizon and the multiple shooting stars faded away.","We were going to my wife’s big family reunion in Auckland, New Zealand, but when we found out that Great Barrier Island, just off the coast, had been recently awarded Dark Sky Sanctuary status—a typically remote area that has an “exceptional or distinguished quality of starry nights”—we thought it would be the perfect place to relax before our busy schedule. It’s the first island and only the fourth location in the world to achieve this status.","After a 28-hour flight with two travel-sick children, our hearts sank when we saw the tiny twin engine 10-seater that was to take us the 90 km across the Hauraki Gulf to Great Barrier Island. But we needn’t have worried. Whether it was the gravity force of the plane climbing or the noise of the engine, it put our three-year-old daughter instantly to sleep until we bumped down on the grass at Claris Airport. Our first empty sick bag against all the odds... Things were looking up.","Great Barrier Island has no public facilities and the 950 people living there (though only about half permanently) rely on solar and wind energy, and bottled gas for cooking. There are no streetlights. There are no cash machines or banks. The police force comprises a husband and wife, and there’s one postman. It’s not just the lack of light but the lack of noise that’s so delightful on this unique and gorgeous scene. It was first discovered by East Polynesians about 700 years ago and the Maori name for the island is Aotea. Captain Cook gave the island its European name, because it acts as a barrier between the Pacific and the Hauraki Gulf.","The climate here is subtropical (亚热带的) like Auckland’s. The island boasts a beautiful wilderness with dense forests, glorious, unspoilt sandy beaches and plenty of bays and a few mountainous areas where there are good walking tracks among the wetlands and valleys. You can birdwatch, dive, surf and boat. The best beaches are on the eastern side of the island where the surf is better, too. The sheltered western side is where you''ll find the best diving and boating. Lots of people come here for the fantastic fishing spots around the island. Like a lot of spots in New Zealand, there are whale-watching trips and you might just catch sight of sharks.","It’s rare to find an island that really does feel undiscovered—but this is it. When one of my wife’s relations, who comes here regularly, found out that we’d been there, he whispered to us, only half-joking: “Shh—don’t tell anyone!” The locals are a relaxed and friendly bunch—a lot of them told us that it’s like what Waiheke Island (now in effect a suburb of Auckland) was in the 1970s when it was a commune of artists and people wanting to escape the city.","Our guide for some of our stay was the inestimable Hilde Hoven, a Dark Sky ambassador who runs Good Heavens with Deborah Kilgallon and Orla Cumisky. They bring their Dobsonian telescope and beanbags (it’s hard work staring up wide-eyed in wonder without neck support) and, our elder daughter was glad to hear, hot chocolate to wherever you are on the island. “It’s odd but when the light readings were done,” said Hilde, explaining how the island was awarded its special status, “they found there was more light pollution on the northern side coming from Fiji, which is about 3,000 km away, than Auckland to the south. It’s pretty dark!”","Beginning their astronomical PowerPoint demonstration using a green laser pointer, Hilde and Orla showed us the Messier 4 spherical cluster (星团) with white dwarf stars (白矮星), Saturn and its rings, the Southern Cross and the Milky Way, which stretched across the sky. Our daughter was especially taken with Hilde’s narrating of the Maori myth of Maui’s fish hook to explain the shape of Scorpius. In the fable, Maui hauled the North Island of New Zealand from the bottom of the ocean with his hook.","We stayed at Mount St Paul’s Estate, a luxurious lodge run by the friendly Chris and Teara, both from Canada. Teara used to be a chef at the Langham in Auckland and so dinner, eaten around a huge circular table (made of one of the most ancient trees in the world), was every bit as mouth-watering as you''d expect. Eating pancakes on the balcony overlooking the unspoilt white sandy beach was a great way to start the day.","Another highlight was an hour-long walk to Kaitoke hot pools in the centre of the island, through wetlands and a forest, where we whiled away a good hour sitting in the pools shaded from the heat by layers of delicate umbrella-like plants.","We also loved visiting the potter (陶艺家) Sarah Harrison, who showed us round her studio at Shoal Bay harbour, and her many pots and jugs, plates and bowls and colourful mosaics (马赛克). In her work, she also uses a lot of materials found on the beach. Our elder daughter loved the gorgeous hidden pool at Medlands beach where the water is separated from the sea in a private rock pool. Other high points were the ancient pohutukawa trees and the incredible views of Okiwi Basin and Whangapoua beach from the top of Windy Canyon, just a 10-minute hike through a narrow valley up some steep wooden steps on the eastern side of the island.","Apparently the island council turned down famous musician Paul McCartney’s application to buy a property at Great Barrier Island because of the unwelcome attention he would have brought. You can see why he wanted to come here; equally, the island knows exactly what kind of star watching it prefers."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-36','cet4-2026-06-1-section-3',0,'choice','36. The author’s daughter slept throughout the last leg of their flight to Great Barrier Island.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','C','参考答案 C。C 段写三岁的女儿在飞机起飞后马上入睡，一直睡到 Claris Airport 降落。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-37','cet4-2026-06-1-section-3',1,'choice','37. The lodge where the author stayed provided very delicious food.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','I','参考答案 I。I 段写住处的晚餐令人垂涎，并提到主厨的工作经历和阳台上的早餐。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-38','cet4-2026-06-1-section-3',2,'choice','38. Many people are attracted to Great Barrier Island because of the incredible fishing sites around it.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','E','参考答案 E。E 段明确说很多人因岛周围极好的垂钓地点而来。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-39','cet4-2026-06-1-section-3',3,'choice','39. A well-known artist failed to purchase a house on Great Barrier Island.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','L','参考答案 L。L 段提到岛议会拒绝了音乐家 Paul McCartney 的购房申请。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-40','cet4-2026-06-1-section-3',4,'choice','40. Unable to fall asleep after a long flight, the author was pleased to enjoy the most gorgeous view of the night sky in his life.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','A','参考答案 A。A 段中作者因时差凌晨清醒，在阳台上欣赏到最壮观的夜空。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-41','cet4-2026-06-1-section-3',5,'choice','41. Great Barrier Island is compared to another island which attracted a lot of artists and people who wished to stay away from city life half a century ago.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','F','参考答案 F。F 段把这里与 20 世纪 70 年代吸引艺术家和逃离城市者的 Waiheke Island 相比。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-42','cet4-2026-06-1-section-3',6,'choice','42. One most memorable part of the author’s visit to Great Barrier Island was a one-hour walk to its centre’s hot springs.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','J','参考答案 J。J 段把徒步一小时到岛中心的 Kaitoke hot pools 称为另一项精彩经历。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-43','cet4-2026-06-1-section-3',7,'choice','43. Great Barrier Island has officially been recognized for its extraordinary starry nights.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','B','参考答案 B。B 段介绍岛屿获得 Dark Sky Sanctuary 地位及其星空质量。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-44','cet4-2026-06-1-section-3',8,'choice','44. Great Barrier Island is not connected to any public power supply lines.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','D','参考答案 D。D 段说明居民依靠太阳能、风能及瓶装燃气，且没有公共设施和路灯。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-3-q-45','cet4-2026-06-1-section-3',9,'choice','45. It is strange that light pollution on Great Barrier Island mainly comes from a faraway island to the north.','[{"key":"A","text":"段落 A"},{"key":"B","text":"段落 B"},{"key":"C","text":"段落 C"},{"key":"D","text":"段落 D"},{"key":"E","text":"段落 E"},{"key":"F","text":"段落 F"},{"key":"G","text":"段落 G"},{"key":"H","text":"段落 H"},{"key":"I","text":"段落 I"},{"key":"J","text":"段落 J"},{"key":"K","text":"段落 K"},{"key":"L","text":"段落 L"}]','G','参考答案 G。G 段指出北方约 3,000 公里外的 Fiji 带来的光污染比南方的 Auckland 更多。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-1-1','cet4-2026-06-1',200,0,'I was glad I had such terrible jetlag.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-1-2','cet4-2026-06-1',200,1,'Wide awake at 3:30 am with our nine-year-old daughter on our lodge balcony, I stared for hours at the most incredible night sky I’ve ever seen before the dawn slowly started to rub out the stars on the horizon and the multiple shooting stars faded away.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-2-1','cet4-2026-06-1',201,0,'We were going to my wife’s big family reunion in Auckland, New Zealand, but when we found out that Great Barrier Island, just off the coast, had been recently awarded Dark Sky Sanctuary status—a typically remote area that has an “exceptional or distinguished quality of starry nights”—we thought it would be the perfect place to relax before our busy schedule.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-2-2','cet4-2026-06-1',201,1,'It’s the first island and only the fourth location in the world to achieve this status.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-3-1','cet4-2026-06-1',202,0,'After a 28-hour flight with two travel-sick children, our hearts sank when we saw the tiny twin engine 10-seater that was to take us the 90 km across the Hauraki Gulf to Great Barrier Island.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-3-2','cet4-2026-06-1',202,1,'But we needn’t have worried.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-3-3','cet4-2026-06-1',202,2,'Whether it was the gravity force of the plane climbing or the noise of the engine, it put our three-year-old daughter instantly to sleep until we bumped down on the grass at Claris Airport.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-3-4','cet4-2026-06-1',202,3,'Our first empty sick bag against all the odds...','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-3-5','cet4-2026-06-1',202,4,'Things were looking up.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-1','cet4-2026-06-1',203,0,'Great Barrier Island has no public facilities and the 950 people living there (though only about half permanently) rely on solar and wind energy, and bottled gas for cooking.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-2','cet4-2026-06-1',203,1,'There are no streetlights.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-3','cet4-2026-06-1',203,2,'There are no cash machines or banks.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-4','cet4-2026-06-1',203,3,'The police force comprises a husband and wife, and there’s one postman.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-5','cet4-2026-06-1',203,4,'It’s not just the lack of light but the lack of noise that’s so delightful on this unique and gorgeous scene.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-6','cet4-2026-06-1',203,5,'It was first discovered by East Polynesians about 700 years ago and the Maori name for the island is Aotea.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-4-7','cet4-2026-06-1',203,6,'Captain Cook gave the island its European name, because it acts as a barrier between the Pacific and the Hauraki Gulf.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-1','cet4-2026-06-1',204,0,'The climate here is subtropical (亚热带的) like Auckland’s.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-2','cet4-2026-06-1',204,1,'The island boasts a beautiful wilderness with dense forests, glorious, unspoilt sandy beaches and plenty of bays and a few mountainous areas where there are good walking tracks among the wetlands and valleys.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-3','cet4-2026-06-1',204,2,'You can birdwatch, dive, surf and boat.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-4','cet4-2026-06-1',204,3,'The best beaches are on the eastern side of the island where the surf is better, too.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-5','cet4-2026-06-1',204,4,'The sheltered western side is where you''ll find the best diving and boating.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-6','cet4-2026-06-1',204,5,'Lots of people come here for the fantastic fishing spots around the island.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-5-7','cet4-2026-06-1',204,6,'Like a lot of spots in New Zealand, there are whale-watching trips and you might just catch sight of sharks.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-6-1','cet4-2026-06-1',205,0,'It’s rare to find an island that really does feel undiscovered—but this is it.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-6-2','cet4-2026-06-1',205,1,'When one of my wife’s relations, who comes here regularly, found out that we’d been there, he whispered to us, only half-joking: “Shh—don’t tell anyone!”','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-6-3','cet4-2026-06-1',205,2,'The locals are a relaxed and friendly bunch—a lot of them told us that it’s like what Waiheke Island (now in effect a suburb of Auckland) was in the 1970s when it was a commune of artists and people wanting to escape the city.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-7-1','cet4-2026-06-1',206,0,'Our guide for some of our stay was the inestimable Hilde Hoven, a Dark Sky ambassador who runs Good Heavens with Deborah Kilgallon and Orla Cumisky.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-7-2','cet4-2026-06-1',206,1,'They bring their Dobsonian telescope and beanbags (it’s hard work staring up wide-eyed in wonder without neck support) and, our elder daughter was glad to hear, hot chocolate to wherever you are on the island.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-7-3','cet4-2026-06-1',206,2,'“It’s odd but when the light readings were done,” said Hilde, explaining how the island was awarded its special status, “they found there was more light pollution on the northern side coming from Fiji, which is about 3,000 km away, than Auckland to the south.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-7-4','cet4-2026-06-1',206,3,'It’s pretty dark!”','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-8-1','cet4-2026-06-1',207,0,'Beginning their astronomical PowerPoint demonstration using a green laser pointer, Hilde and Orla showed us the Messier 4 spherical cluster (星团) with white dwarf stars (白矮星), Saturn and its rings, the Southern Cross and the Milky Way, which stretched across the sky.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-8-2','cet4-2026-06-1',207,1,'Our daughter was especially taken with Hilde’s narrating of the Maori myth of Maui’s fish hook to explain the shape of Scorpius.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-8-3','cet4-2026-06-1',207,2,'In the fable, Maui hauled the North Island of New Zealand from the bottom of the ocean with his hook.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-9-1','cet4-2026-06-1',208,0,'We stayed at Mount St Paul’s Estate, a luxurious lodge run by the friendly Chris and Teara, both from Canada.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-9-2','cet4-2026-06-1',208,1,'Teara used to be a chef at the Langham in Auckland and so dinner, eaten around a huge circular table (made of one of the most ancient trees in the world), was every bit as mouth-watering as you''d expect.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-9-3','cet4-2026-06-1',208,2,'Eating pancakes on the balcony overlooking the unspoilt white sandy beach was a great way to start the day.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-10-1','cet4-2026-06-1',209,0,'Another highlight was an hour-long walk to Kaitoke hot pools in the centre of the island, through wetlands and a forest, where we whiled away a good hour sitting in the pools shaded from the heat by layers of delicate umbrella-like plants.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-11-1','cet4-2026-06-1',210,0,'We also loved visiting the potter (陶艺家) Sarah Harrison, who showed us round her studio at Shoal Bay harbour, and her many pots and jugs, plates and bowls and colourful mosaics (马赛克).','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-11-2','cet4-2026-06-1',210,1,'In her work, she also uses a lot of materials found on the beach.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-11-3','cet4-2026-06-1',210,2,'Our elder daughter loved the gorgeous hidden pool at Medlands beach where the water is separated from the sea in a private rock pool.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-11-4','cet4-2026-06-1',210,3,'Other high points were the ancient pohutukawa trees and the incredible views of Okiwi Basin and Whangapoua beach from the top of Windy Canyon, just a 10-minute hike through a narrow valley up some steep wooden steps on the eastern side of the island.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-12-1','cet4-2026-06-1',211,0,'Apparently the island council turned down famous musician Paul McCartney’s application to buy a property at Great Barrier Island because of the unwelcome attention he would have brought.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-1-section-3-sentence-12-2','cet4-2026-06-1',211,1,'You can see why he wanted to come here; equally, the island knows exactly what kind of star watching it prefers.','cet4-2026-06-1-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-1-section-4','cet4-2026-06-1',3,'reading','仔细阅读 · Passage One（46–50）','阅读文章，为每题选择一个最佳答案。','["Is organic food worth the higher price? It’s the classic grocery store dilemma. On the one hand, your family dinner table deserves only the best. On the other hand, your wallet can only stretch so far.","Whether or not to buy organic is a personal decision, said Mike von Massow, professor of Food Agriculture.","Science won’t give a clear-cut answer to the question of whether organic food is “better.” There are often trade-offs (权衡) and answers become less definitive depending on the product under consideration.","One thing is definitive: Organic and conventionally grown food are equally nutritious. From a nutrition point of view, there is no difference between organic and traditionally grown products.","Organic products don’t necessarily have fewer pesticides (杀虫剂)—in fact, they may have more. There is also no big difference between organic and non-organic products from a food-safety perspective. Even organic growers use pesticides. Testing shows little if any pesticide remains on conventionally grown products.","In fact, organic farmers often use larger quantities of pesticide because they can only use the natural variety of insect-killers. Chemical pesticides generally kill a much wider range of pests (害虫) than any single natural pesticide.","The use of animal waste in organic agriculture can also be a factor in the spread of bacteria like E. coli and salmonella. Over the past 10 years, Canada has seen more food-safety recalls for organic products, proportionally, than for conventional products.","On the whole, organic agriculture may have a smaller environmental footprint. That’s mostly because the risk of groundwater contamination from organic farming is lower. Organic farmers never used neonics, the controversial pesticides that have been linked to shrinking bee populations worldwide.","Traditional agriculture has been making “dramatic improvements” to reduce its impact on the environment.","It isn’t a black-and-white picture, though.","Organic farming is much less efficient when it comes to land use, although yields vary considerably depending on the crop.","On the other hand, advocates of organic farming argue yields and efficiency could be significantly improved if the food industry devoted as much research and money to organic farming as it does conventional agriculture."]','["Is organic food worth the higher price? It’s the classic grocery store dilemma. On the one hand, your family dinner table deserves only the best. On the other hand, your wallet can only stretch so far.","Whether or not to buy organic is a personal decision, said Mike von Massow, professor of Food Agriculture.","Science won’t give a clear-cut answer to the question of whether organic food is “better.” There are often trade-offs (权衡) and answers become less definitive depending on the product under consideration.","One thing is definitive: Organic and conventionally grown food are equally nutritious. From a nutrition point of view, there is no difference between organic and traditionally grown products.","Organic products don’t necessarily have fewer pesticides (杀虫剂)—in fact, they may have more. There is also no big difference between organic and non-organic products from a food-safety perspective. Even organic growers use pesticides. Testing shows little if any pesticide remains on conventionally grown products.","In fact, organic farmers often use larger quantities of pesticide because they can only use the natural variety of insect-killers. Chemical pesticides generally kill a much wider range of pests (害虫) than any single natural pesticide.","The use of animal waste in organic agriculture can also be a factor in the spread of bacteria like E. coli and salmonella. Over the past 10 years, Canada has seen more food-safety recalls for organic products, proportionally, than for conventional products.","On the whole, organic agriculture may have a smaller environmental footprint. That’s mostly because the risk of groundwater contamination from organic farming is lower. Organic farmers never used neonics, the controversial pesticides that have been linked to shrinking bee populations worldwide.","Traditional agriculture has been making “dramatic improvements” to reduce its impact on the environment.","It isn’t a black-and-white picture, though.","Organic farming is much less efficient when it comes to land use, although yields vary considerably depending on the crop.","On the other hand, advocates of organic farming argue yields and efficiency could be significantly improved if the food industry devoted as much research and money to organic farming as it does conventional agriculture."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-4-q-46','cet4-2026-06-1-section-4',0,'choice','46. What is the classic grocery store dilemma?','[{"key":"A","text":"Whether or not one should eat organic food."},{"key":"B","text":"Whether or not one can stretch their wallet far."},{"key":"C","text":"Organic food costs more but it certainly tastes better."},{"key":"D","text":"One wants the best food but their budget is limited."}]','D','参考答案 D。首段的两难是希望给家人最好的食物，同时预算有限。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-4-q-47','cet4-2026-06-1-section-4',1,'choice','47. What do we learn about organic food from science?','[{"key":"A","text":"Whether it is any better remains uncertain."},{"key":"B","text":"Whether it is healthier is under consideration."},{"key":"C","text":"Whether it is more nutritious than conventional food is arguable."},{"key":"D","text":"Whether it is going to replace conventional food is still unclear."}]','A','参考答案 A。第三段明确说科学无法清楚回答有机食品是否“更好”，不同产品存在权衡。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-4-q-48','cet4-2026-06-1-section-4',2,'choice','48. What does the passage say about organic and non-organic products as far as food safety is concerned?','[{"key":"A","text":"Their difference is the conventions used to test them."},{"key":"B","text":"They differ in how much pesticide remains on them."},{"key":"C","text":"One relies on pesticides whereas the other does not."},{"key":"D","text":"There is no substantial difference between the two."}]','D','参考答案 D。原文从食品安全角度说明两者没有很大的差异。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-4-q-49','cet4-2026-06-1-section-4',3,'choice','49. What does the author say about organic farming?','[{"key":"A","text":"It may be blamed for the shrinking bee populations in the world."},{"key":"B","text":"It minimizes the use of controversial pesticides in its operations."},{"key":"C","text":"It may impact the environment less than conventional farming."},{"key":"D","text":"It contaminates groundwater as much as conventional farming."}]','C','参考答案 C。原文写有机农业整体上可能具有较小的环境足迹。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-1-section-4-q-50','cet4-2026-06-1-section-4',4,'choice','50. What do advocates of organic farming argue about its yields and efficiency?','[{"key":"A","text":"They would increase quickly with the emergence of new technologies."},{"key":"B","text":"They would improve remarkably with more research and investment."},{"key":"C","text":"They would be achieved along with enormous health benefits."},{"key":"D","text":"They would considerably lower the cost to the environment."}]','B','参考答案 B。末段的支持者认为投入更多研究和资金可显著提高产量与效率。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
