INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-3-3','cet4-2026-06-2',202,2,'Overall, women who were highly fit compared to those who were moderately fit decreased their risk of dementia by 88%.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-3-4','cet4-2026-06-2',202,3,'The few highly fit women who did develop dementia became symptomatic at age 90 on average, 11 years later than the moderately fit.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-4-1','cet4-2026-06-2',203,0,'“I’m very surprised that the finding was so strong,” said Ingmar Skoog, the paper’s senior author and a psychiatry (精神病学) professor at The University of Gothenburg in Sweden.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-4-2','cet4-2026-06-2',203,1,'“It really shows the importance of exercise.”','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-1','cet4-2026-06-2',204,0,'Dementia, as defined in medical dictionaries, is a broad term that describes a loss of thinking ability, memory, attention, logical reasoning, and other mental abilities.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-2','cet4-2026-06-2',204,1,'These changes are severe enough to interfere with social or occupational functioning.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-3','cet4-2026-06-2',204,2,'Dementia isn’t a disease.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-4','cet4-2026-06-2',204,3,'Instead, it’s a group of symptoms caused by other conditions.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-5','cet4-2026-06-2',204,4,'It happens when the parts of your brain used for learning, memory, decision making, and language are damaged or diseased.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-6','cet4-2026-06-2',204,5,'About 5%–8% of adults over age 65 have some form of dementia.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-7','cet4-2026-06-2',204,6,'This percentage doubles every 5 years after 65.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-5-8','cet4-2026-06-2',204,7,'As many as half of people in their 80s have some dementia.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-6-1','cet4-2026-06-2',205,0,'Dementia is not temporary confusion or forgetfulness that might result from an infection that heals without treatment.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-6-2','cet4-2026-06-2',205,1,'It can also come from an underlying (潜在的) illness or side effects of medications.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-6-3','cet4-2026-06-2',205,2,'Dementia typically gets worse over time.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-6-4','cet4-2026-06-2',205,3,'People with dementia have problems with thinking and remembering that affect their ability to manage their daily life.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-7-1','cet4-2026-06-2',206,0,'Dementia is typically associated with declines in cognitive function.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-7-2','cet4-2026-06-2',206,1,'Yet researchers have found an association between dementia and declines in hearing and other basic sensory functions.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-8-1','cet4-2026-06-2',207,0,'Though the study mentioned above was fairly small(only 191 women took the initial fitness test, which means it’s hard to maintain statistical significance while breaking the group down into sub-categories of more or less fit), it does give us hope that dementia can be prevented or delayed through exercise in one’s middle age.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-9-1','cet4-2026-06-2',208,0,'Alzheimer’s (阿尔茨海默症) and other dementias are believed to begin 15–20 years before symptoms even appear, so it makes sense that exercising in mid-life would affect the risk, Skoog said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-9-2','cet4-2026-06-2',208,1,'Exercise alone is not likely to prevent Alzheimer’s, but the study shows people are not helpless in the face of one of the most feared, costliest and common diseases of old age, he added.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-9-3','cet4-2026-06-2',208,2,'And the same activities that help prevent Alzheimer’s—including avoiding smoking, getting adequate exercise and sleep and eating a healthy diet—also prevent heart disease, he said, making them even more worthwhile.“ You can do something yourself to decrease your odds,” Skoog said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-10-1','cet4-2026-06-2',209,0,'Maintaining a healthy lifestyle in mid-life, decades before disease sets in, makes sense, said David Knopman, a fellow of the American Academy of Neurology, who was not involved in the study.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-10-2','cet4-2026-06-2',209,1,'“I suspect it’s a dose,” said Knopman, also associate director of the Alzheimer’s Disease Research Center at Mayo Clinic in Rochester, Minnesota.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-10-3','cet4-2026-06-2',209,2,'“Starting in late life is better than not starting at all, but starting in mid-life seems to offer a larger benefit.”','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-11-1','cet4-2026-06-2',210,0,'Although it is not entirely clear why exercise helps put off or prevent Alzheimer’s, Knopman said it’s likely that exercise maintains good blood flow to the brain.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-11-2','cet4-2026-06-2',210,1,'“When the brain is healthier from a vascular (血管的) point of view, it can absorb more Alzheimer’s pathogen (病原体) before people become symptomatic,” he said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-12-1','cet4-2026-06-2',211,0,'The message isn’t that everyone needs to run marathons in middle age, Knopman said, but a healthy lifestyle pays off.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-13-1','cet4-2026-06-2',212,0,'This type of study can’t say exactly what kind of exercise is best, or how much is needed—only a study that has a placebo (安慰剂) group and tracks people going forward can do that, said Keith Fargo, director of scientific programs and outreach at the non-profit Alzheimer’s Association.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-13-2','cet4-2026-06-2',212,1,'“The literature has not yet settled on an amount or type of exercise that is going to be key, although the bulk of literature has suggested that aerobic (有氧的) exercise is what you need to be doing,” he said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-13-3','cet4-2026-06-2',212,2,'That doesn’t mean you have to compete in marathons but “more than a 10-min dog walk” would be a good idea, Fargo said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-14-1','cet4-2026-06-2',213,0,'Several lifestyle studies are getting underway soon, including one backed by the Alzheimer’s Association called the US POINTER study, which will offer at-risk adults, ages 60–79, a series of lifestyle interventions (干预) to see if they impact Alzheimer’s risk.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-14-2','cet4-2026-06-2',213,1,'That and other Alzheimer’s-related studies are always looking for volunteers to participate, he said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-15-1','cet4-2026-06-2',214,0,'In the next three to five years, these studies should allow researchers to provide clearer recommendations for exercise and other lifestyle modifications that might reduce Alzheimer’s risk, such as sleep, diet and social activities, Fargo said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-15-2','cet4-2026-06-2',214,1,'But it’s already quite clear that exercising at any point in life is better for your brain than not exercising at all, Fargo added.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-16-1','cet4-2026-06-2',215,0,'“If you don’t want to have dementia when you’re 80, the time to start getting fit is now,” he said.','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-3-sentence-16-2','cet4-2026-06-2',215,1,'“It may not necessarily give you a longer life, but there’s a compelling body of work that it will give you more good years.”','cet4-2026-06-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-2-section-4','cet4-2026-06-2',3,'reading','仔细阅读 · Passage One（46–50）','阅读文章，为每题选择一个最佳答案。','["People who systematically underestimate themselves and their own performance suffer from the so-called Impostor Phenomenon. They think that any success is due to external circumstances or just luck and chance. Those people live in constant fear that their “deception” will be exposed.","It is common for people to question their abilities now and again. A healthy amount of reflection and self-doubt can protect a person from acting impulsively. However, there are people who are permanently plagued by a massive amount of self-doubt despite delivering a good performance. They think that all of their successes are not a product of their skill or hard work, instead they attribute their own successes to external circumstances, for example, to luck and chance, or believe that their performance is massively overestimated by others. Failures, on the other hand, are always internalised as the result of their own shortcomings.","Psychologists from Martin Luther University Halle-Wittenberg examined the topic for the first time under real-life conditions. Seventy-six participants completed a range of intelligence tests and received positive feedback on them, regardless of their actual performance. They were then asked why they think they did so well.","The study showed two things: First, the self-reported degree of Impostor Phenomenon is not related to actual measured intelligence or performance. Secondly, the test supported the assumption that people with a tendency to exhibit the Impostor Phenomenon devalue their objectively measured performance and attribute positive results to external causes such as luck and chance, but not to their own abilities. These results are also completely unrelated to age and gender.","A permanent underestimation of one’s own abilities is often accompanied by the fear that this supposed intellectual deception will be exposed sooner or later and that they will pay the price for this. The Impostor Phenomenon was first described in 1978 by US psychologists Pauline Clance and Suzanne Imes. They observed that there is a particularly high number of successful women who do not think they are very intelligent. The Impostor Phenomenon is not defined as a mental illness. However, people who suffer from it show a higher vulnerability to depression."]','["People who systematically underestimate themselves and their own performance suffer from the so-called Impostor Phenomenon. They think that any success is due to external circumstances or just luck and chance. Those people live in constant fear that their “deception” will be exposed.","It is common for people to question their abilities now and again. A healthy amount of reflection and self-doubt can protect a person from acting impulsively. However, there are people who are permanently plagued by a massive amount of self-doubt despite delivering a good performance. They think that all of their successes are not a product of their skill or hard work, instead they attribute their own successes to external circumstances, for example, to luck and chance, or believe that their performance is massively overestimated by others. Failures, on the other hand, are always internalised as the result of their own shortcomings.","Psychologists from Martin Luther University Halle-Wittenberg examined the topic for the first time under real-life conditions. Seventy-six participants completed a range of intelligence tests and received positive feedback on them, regardless of their actual performance. They were then asked why they think they did so well.","The study showed two things: First, the self-reported degree of Impostor Phenomenon is not related to actual measured intelligence or performance. Secondly, the test supported the assumption that people with a tendency to exhibit the Impostor Phenomenon devalue their objectively measured performance and attribute positive results to external causes such as luck and chance, but not to their own abilities. These results are also completely unrelated to age and gender.","A permanent underestimation of one’s own abilities is often accompanied by the fear that this supposed intellectual deception will be exposed sooner or later and that they will pay the price for this. The Impostor Phenomenon was first described in 1978 by US psychologists Pauline Clance and Suzanne Imes. They observed that there is a particularly high number of successful women who do not think they are very intelligent. The Impostor Phenomenon is not defined as a mental illness. However, people who suffer from it show a higher vulnerability to depression."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-4-q-46','cet4-2026-06-2-section-4',0,'choice','46. What do we learn from the passage about people who suffer from the so-called Impostor Phenomenon?','[{"key":"A","text":"They systematically underestimate their chance of success."},{"key":"B","text":"They tend to attribute their achievements to good fortune."},{"key":"C","text":"They seem to live in constant fear of being deceived."},{"key":"D","text":"They generally rely on luck and chance for success."}]','B','参考答案 B。首段说这类人把成功归因于外部环境、运气和偶然因素。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-4-q-47','cet4-2026-06-2-section-4',1,'choice','47. What do people with a healthy amount of reflection and self-doubt tend to do?','[{"key":"A","text":"Credit all their successes to hard work."},{"key":"B","text":"Strive hard to perfect their skills."},{"key":"C","text":"Refrain from acting on impulse."},{"key":"D","text":"Deliver a better performance."}]','C','参考答案 C。第二段明确说适度反思和自我怀疑可以避免冲动行事。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-4-q-48','cet4-2026-06-2-section-4',2,'choice','48. What do Impostor Phenomenon sufferers often do according to psychologists from Martin Luther University Halle-Wittenberg?','[{"key":"A","text":"Attribute their accomplishments to others."},{"key":"B","text":"Deny their actual measured intelligence."},{"key":"C","text":"Claim to have confidence in their own abilities."},{"key":"D","text":"Mark down their objectively rated performance."}]','D','参考答案 D。研究支持这类人会低估客观测量得到的自身表现。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-4-q-49','cet4-2026-06-2-section-4',3,'choice','49. What happens when a person permanently underestimates their own abilities?','[{"key":"A","text":"They will focus their attention on external factors."},{"key":"B","text":"They will be fearful of potential consequences."},{"key":"C","text":"They will count on good fortune for success."},{"key":"D","text":"They will keep improving their own skills."}]','B','参考答案 B。末段说长期低估能力的人害怕被揭穿并为此付出代价。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-4-q-50','cet4-2026-06-2-section-4',4,'choice','50. What did US psychologists Pauline Clance and Suzanne Imes say about Impostor Phenomenon sufferers?','[{"key":"A","text":"They are more liable to have depression."},{"key":"B","text":"They seldom realise their potential fully."},{"key":"C","text":"They will develop mental illnesses."},{"key":"D","text":"They will pay higher prices one day."}]','A','参考答案 A。末段指出虽不被定义为精神疾病，但患者更容易受到抑郁影响。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-1-1','cet4-2026-06-2',300,0,'People who systematically underestimate themselves and their own performance suffer from the so-called Impostor Phenomenon.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-1-2','cet4-2026-06-2',300,1,'They think that any success is due to external circumstances or just luck and chance.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-1-3','cet4-2026-06-2',300,2,'Those people live in constant fear that their “deception” will be exposed.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-2-1','cet4-2026-06-2',301,0,'It is common for people to question their abilities now and again.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-2-2','cet4-2026-06-2',301,1,'A healthy amount of reflection and self-doubt can protect a person from acting impulsively.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-2-3','cet4-2026-06-2',301,2,'However, there are people who are permanently plagued by a massive amount of self-doubt despite delivering a good performance.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-2-4','cet4-2026-06-2',301,3,'They think that all of their successes are not a product of their skill or hard work, instead they attribute their own successes to external circumstances, for example, to luck and chance, or believe that their performance is massively overestimated by others.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-2-5','cet4-2026-06-2',301,4,'Failures, on the other hand, are always internalised as the result of their own shortcomings.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-3-1','cet4-2026-06-2',302,0,'Psychologists from Martin Luther University Halle-Wittenberg examined the topic for the first time under real-life conditions.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-3-2','cet4-2026-06-2',302,1,'Seventy-six participants completed a range of intelligence tests and received positive feedback on them, regardless of their actual performance.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-3-3','cet4-2026-06-2',302,2,'They were then asked why they think they did so well.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-4-1','cet4-2026-06-2',303,0,'The study showed two things: First, the self-reported degree of Impostor Phenomenon is not related to actual measured intelligence or performance.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-4-2','cet4-2026-06-2',303,1,'Secondly, the test supported the assumption that people with a tendency to exhibit the Impostor Phenomenon devalue their objectively measured performance and attribute positive results to external causes such as luck and chance, but not to their own abilities.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-4-3','cet4-2026-06-2',303,2,'These results are also completely unrelated to age and gender.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-5-1','cet4-2026-06-2',304,0,'A permanent underestimation of one’s own abilities is often accompanied by the fear that this supposed intellectual deception will be exposed sooner or later and that they will pay the price for this.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-5-2','cet4-2026-06-2',304,1,'The Impostor Phenomenon was first described in 1978 by US psychologists Pauline Clance and Suzanne Imes.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-5-3','cet4-2026-06-2',304,2,'They observed that there is a particularly high number of successful women who do not think they are very intelligent.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-5-4','cet4-2026-06-2',304,3,'The Impostor Phenomenon is not defined as a mental illness.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2026-06-2-section-4-sentence-5-5','cet4-2026-06-2',304,4,'However, people who suffer from it show a higher vulnerability to depression.','cet4-2026-06-2-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2026-06-2-section-5','cet4-2026-06-2',4,'reading','仔细阅读 · Passage Two（51–55）','阅读文章，为每题选择一个最佳答案。','["Music is a universal language. In every culture and country, you will find music. It is vitally important across the globe and has the potential to bring people together in peace and harmony. One of my favorite experiences in music is seeing musicians from different cultures come together and perform as a group. When each culture brings its own unique qualities to the group, an entirely new sound is achieved. This can create extraordinary results. People can communicate with each other using music as the common language.","One common musical thread between cultures is known as the pentatonic scale. It is astonishing how many cultures share this tool in approaching music. The pentatonic scale consists of five notes; “penta-” meaning 5, and “tonic” meaning tone or note. This scale can be found in music everywhere including that of Native Americans, Africans, and Asians. It is also found in popular music, blues, jazz, and rock. Using this five-note scale, musicians from around the globe have a medium through which they can relate, communicate, perform, and ultimately understand each other.","Music is tied to specific perceptual (感知的), mental, and emotional faculties, including language (all societies put words to their songs), motor control (people in all societies dance), sound analysis (all musical systems have a distinct pitch and quality), and aesthetics (美感) (their tunes and rhythms are balanced between repetitiveness and chaos).","There is no known society that existed without music. Although each culture has their own specific style and approach to music, you will find that the purposes behind music are very similar across the board. Music essentially serves to express or change emotions. It can cheer you up, sadden you, anger you or excite you. Music is often ceremonial: used in religion, ceremony, and celebration. Music can simply be recreational: entertaining, joyful and fun. Any way you have used music, it is almost certain that every other culture has used music in the very same way. And that is something that bonds all of us. We all share a deep love for music and it has the power to unite us."]','["Music is a universal language. In every culture and country, you will find music. It is vitally important across the globe and has the potential to bring people together in peace and harmony. One of my favorite experiences in music is seeing musicians from different cultures come together and perform as a group. When each culture brings its own unique qualities to the group, an entirely new sound is achieved. This can create extraordinary results. People can communicate with each other using music as the common language.","One common musical thread between cultures is known as the pentatonic scale. It is astonishing how many cultures share this tool in approaching music. The pentatonic scale consists of five notes; “penta-” meaning 5, and “tonic” meaning tone or note. This scale can be found in music everywhere including that of Native Americans, Africans, and Asians. It is also found in popular music, blues, jazz, and rock. Using this five-note scale, musicians from around the globe have a medium through which they can relate, communicate, perform, and ultimately understand each other.","Music is tied to specific perceptual (感知的), mental, and emotional faculties, including language (all societies put words to their songs), motor control (people in all societies dance), sound analysis (all musical systems have a distinct pitch and quality), and aesthetics (美感) (their tunes and rhythms are balanced between repetitiveness and chaos).","There is no known society that existed without music. Although each culture has their own specific style and approach to music, you will find that the purposes behind music are very similar across the board. Music essentially serves to express or change emotions. It can cheer you up, sadden you, anger you or excite you. Music is often ceremonial: used in religion, ceremony, and celebration. Music can simply be recreational: entertaining, joyful and fun. Any way you have used music, it is almost certain that every other culture has used music in the very same way. And that is something that bonds all of us. We all share a deep love for music and it has the power to unite us."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-5-q-51','cet4-2026-06-2-section-5',0,'choice','51. In what way is music important?','[{"key":"A","text":"It is able to create novel and extraordinary emotions."},{"key":"B","text":"It has the power to unite people throughout the world."},{"key":"C","text":"It allows different cultural groups to sing in harmony."},{"key":"D","text":"It is the only language favored by all peoples of the world."}]','B','参考答案 B。首段及末段强调音乐能够把世界各地的人联系在一起。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-5-q-52','cet4-2026-06-2-section-5',1,'choice','52. Why does the author like to see musicians from different cultures perform together?','[{"key":"A","text":"Their musical experience can be compared."},{"key":"B","text":"A novel language can be created."},{"key":"C","text":"Their unique skills can be displayed."},{"key":"D","text":"Fantastic results can be achieved."}]','D','参考答案 D。首段写不同文化的独特品质融合后产生新声音，并创造 extraordinary results。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-5-q-53','cet4-2026-06-2-section-5',2,'choice','53. What does the passage say about the pentatonic scale?','[{"key":"A","text":"It is present in music all around the world."},{"key":"B","text":"It is helpful to understanding music."},{"key":"C","text":"It is the basis for musicians’ creation."},{"key":"D","text":"It is a medium for ordinary people to relate."}]','A','参考答案 A。第二段明确说五声音阶存在于世界各地的音乐中。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-5-q-54','cet4-2026-06-2-section-5',3,'choice','54. What is the fundamental role of music in people’s life?','[{"key":"A","text":"To bring them together."},{"key":"B","text":"To show their identity."},{"key":"C","text":"To express their emotions."},{"key":"D","text":"To keep them entertained."}]','C','参考答案 C。末段说音乐的基本作用是表达或改变情绪。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2026-06-2-section-5-q-55','cet4-2026-06-2-section-5',4,'choice','55. In what aspect is music similar throughout the world?','[{"key":"A","text":"The way people respond to it."},{"key":"B","text":"The role it plays in society."},{"key":"C","text":"The joy it brings to people."},{"key":"D","text":"The way it is made use of."}]','D','参考答案 D。末段列举情绪表达、仪式和娱乐等用途，并说每种文化几乎都以相同方式使用音乐。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
